quests[24872] = { id = 24872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Respite for a Tormented Soul", description = "Take this Life Crystal, and have your companions take one as well. It contains potent energies from the verdant Dragonshrine in Dragonblight, and it was my own secret to resisting the dark magics of this place for so long.\n\nWhen you face Sindragosa, battle her until she is weakened, and then have your companions use these Crystals to coax out the essence that is dormant within her. If you then defeat her, you should be able to recover it and return it to Wyrmrest Temple in Dragonblight.", sourceObjective = "Use the Life Crystals to preserve Sindragosa's Essence.", progress = "What do you hold there in your hands, mortal?", completion = "<Kalecgos sighs>\n\nSo much suffering, so much needless destruction. These have not been kind times for my brothers and sisters. But thanks to your efforts, brave adventurers, this darkened yet still noble soul may find peace at last.\n\nRest now, Sindragosa. You are home....", sourceObjectiveStatus = "unverified-source-field" }
quests[24873] = { id = 24873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Residue Rendezvous", description = "Professor Putricide has been holed up in his foul laboratory, experimenting and refining increasingly lethal strains of blight to be used against us. If only we could obtain pure samples of the toxins, our researchers could concoct an antidote that would save countless lives.\n\nBut there's a catch -- a proper sample will need to mix two active strains within a living host. Should you have the... misfortune... of becoming such a host, please return here immediately so that we can harvest you for study.", sourceObjective = "Return to Alchemist Adrianna while infected with Orange and Green Blight.", progress = "Putricide's Blight is one of the Scourge's most powerful weapons against us.", completion = "At last, we have live specimens to study! You have helped to save countless lives this day, {name}.\n\nPlease, take this as a token of thanks for this great deed.", sourceObjectiveStatus = "unverified-source-field" }
quests[24874] = { id = 24874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Quickening", description = "These Scourge bloodsuckers -- San'layn they call themselves - give me the creeps. We've had one of our best men keeping an eye on them. But this morning he got sloppy and got himself taken prisoner. He's being interrogated by the Queen herself right now, and his cries echo through the Crimson Halls. Please, save him before it's too late!", sourceObjective = "Rescue Infiltrator Minchar before he is executed.", completion = "Whew, I thought I was a goner! I heard talk of a resurrection ritual going on in these Halls and went in for a closer look, but one of those blasted vampires sniffed me out. They strung me up here, draining my life energy and hoping I'd break and divulge our plans of attack. As if I even know what Tirion has planned!\n\nPlease, take these spoils of war as a small token of gratitude for saving my life.", sourceObjectiveStatus = "unverified-source-field" }
quests[24875] = { id = 24875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deprogramming", description = "We had hoped to place a man on the inside of the Cult of the Damned, to give us an inside angle on the Lich King's machinations, but we... underestimated the persuasive powers of Arthas and his dark minister, Lady Deathwhisper.\n\nOur man, Darnavan, is one of them now.\n\nIf you plan on fighting your way through the Oratory ahead, please keep your eyes peeled for Darnavan. If you can bring him back to us alive, we can attempt to reverse the Cult's brainwashing.", sourceObjective = "Defeat Lady Deathwhisper while ensuring that Darnavan survives.", progress = "Darnavan has been among the Cult for so long now that there is no telling how he will react. He is a well-trained warrior, so be on your guard!", completion = "Thank you, {name}!\n\nI owe you a debt of gratitude for rescuing a friend whom I had thought forever lost to the clutches of the Cult. And the Argent Crusade owes you a debt for the invaluable intelligence Darnavan brings with him from his time walking the halls of this Citadel as one of the Cult.\n\nPlease, take this as a token of this appreciation, and may the Light bolster you as you carve a path through this terrible place.", sourceObjectiveStatus = "unverified-source-field" }
quests[24876] = { id = 24876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Ramparts", description = "As if this place weren't enough of a madhouse to begin with, we're fighting a war on two fronts up here, with the Scourge on one side and those blasted Horde dogs on our other flank!\n\nWe are here to clear a safe landing for our vessels, but a behemoth of a giant on the other side of the Ramparts is hurling debris at anything that comes close and keeping our smaller ships at bay.\n\nI'll be honest -- he's a bit much for us to handle, but you and your companions look up to the task.", sourceObjective = "Slay the Rotting Frost Giant.", progress = "Is the giant dead?", completion = "The giant is dead? Praise the Light!\n\nThe way onward and upward is clear. Take some of these spoils of the battle as a token of our gratitude, and we will drink together in celebration once the Frozen Throne has been ground to dust!", sourceObjectiveStatus = "unverified-source-field" }
quests[24877] = { id = 24877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Ramparts", description = "As if this place weren't enough of a madhouse to begin with, we're fighting a war on two fronts up here, with the Scourge on one side and those blasted Alliance dogs on our other flank!\n\nWe are here to clear a safe landing for our vessels, but a behemoth of a giant on the other side of the Ramparts is hurling debris at anything that comes close and keeping our smaller ships at bay.\n\nI'll be honest -- he's a bit much for us to handle, but you and your companions look up to the task.", sourceObjective = "Slay the Rotting Frost Giant.", progress = "Is the giant dead?", completion = "The giant is dead? For the Horde!\n\nThe way onward and upward is clear. Take some of these spoils of the battle as a token of our gratitude, and we will drink together in celebration once the Frozen Throne has been ground to dust!", sourceObjectiveStatus = "unverified-source-field" }
quests[24878] = { id = 24878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Residue Rendezvous", description = "Professor Putricide has been holed up in his foul laboratory, experimenting and refining increasingly lethal strains of blight to be used against us. If only we could obtain pure samples of the toxins, our researchers could concoct an antidote that would save countless lives.\n\nIf you happen to come across live specimens, please return here immediately so that we can harvest them for study.", sourceObjective = "Return to Alchemist Adrianna while infected with Orange and Green Blight.", progress = "Putricide's blight is one of the Scourge's most powerful weapons against us.", completion = "At last, we have live specimens to study! You have helped to save countless lives this day, {name}.\n\nPlease, take this as a token of thanks for this great deed.", sourceObjectiveStatus = "unverified-source-field" }
quests[24879] = { id = 24879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Quickening", description = "These Scourge bloodsuckers -- San'layn they call themselves -- give me the creeps. We've had one of our best men keeping an eye on them. But this morning he got sloppy and got himself taken prisoner. He's being interrogated by the Queen herself right now, and his cries echo through the Crimson Halls. Please, save him before it's too late!", sourceObjective = "Rescue Infiltrator Minchar before he is executed.", completion = "Whew, I thought I was a goner! I heard talk of a resurrection ritual going on in these Halls and went in for a closer look, but one of those blasted vampires sniffed me out. They strung me up here, draining my life energy and hoping I'd break and divulge our plans of attack. As if I even know what Tirion has planned!\n\nPlease, take these spoils of war as a small token of gratitude for saving my life.", sourceObjectiveStatus = "unverified-source-field" }
