quests[24896] = { id = 24896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Classic Random 65-70 (Nth)" }
quests[24897] = { id = 24897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Back to Town", description = "We were wrong. It wasn't the naga that were preparing to attack... it was the nearby Oomlot tribe.\n\n{name}, you need to get back to the Town-In-A-Box. The pygmies are already attacking!\n\nHere, take this. We bought it off of a pygmy who said it used to belong to some great leader of theirs. Someone whose name translates as Dark Tan Helmet.\n\nIt should fool them so that they don't attack you.", sourceObjective = "Speak with Sassy Hardwrench at the Town-In-A-Box on the Lost Isles.", completion = "{name}? We're saved!\n\nWho am I kidding? We're all going to die!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[24901] = { id = 24901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Town-In-A-Box: Under Attack", description = "{name}, you have to defend us!\n\nI had the eggheads deploy the town's cannon defenses, but it seems like there's an unlimited supply of these Oomlot warriors!\n\nGet your behind into one of those B.C. Eliminators and eliminate the pygmy threat to the town!", sourceObjective = "Use a B.C. Eliminator to defeat 30 Oomlot Warriors.", progress = "That's not enough, hon. Can you take care of more of them?", completion = "Okay, I think that's good enough for now, but they took a bunch of the townsfolk captive.\n\nWe're going to have to take the fight to them!", sourceObjectiveStatus = "unverified-source-field" }
quests[24902] = { id = 24902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunt For Sylvanas", description = "It's true then?  Gilneas has lost her favorite son.\n\nWe will mourn when this is all over but not a day sooner.\n\nWe will not allow ourselves the luxury of grief while the enemy still breathes Gilnean air.\n\nMy father's men are ready to strike while we still have the Banshee Queen's trail.  Just say the word if you're ready.  Liam deserves swift vengeance.", sourceObjective = "Follow Tobias Mistmantle in the Hunt for Sylvanas.", progress = "Did you find her, {name}?", completion = "The Plague?  Something so heinous that not even the orcs condone its use?  I'd say this warrants notifying King Greymane.", sourceObjectiveStatus = "unverified-source-field" }
quests[24903] = { id = 24903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance or Survival", description = "Tell Greymane that we have trackers on Sylvanas and tell him about the Plague.\n\nThe decision will be his.  Launch an all out attack against the leader of the Forsaken or try to evacuate our survivors.", sourceObjective = "Speak to King Genn Greymane at Greymane Court in Gilneas City.", completion = "You present me with the most difficult choice of my life, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24904] = { id = 24904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Gilneas City", description = "The time has come, {name}.  We've rallied and armed every available Gilnean.\n\nIt is time to meet the enemy head on.  Time to settle the score with Sylvanas and her Forsaken dogs once and for all.\n\nLiam is heading the assault from this gate.  King Greymane and my father are leading the assault on the other districts.\n\nYou have a crucial role to play in this as well.  Take this rapier.  Use it to inspire our men and women in combat.  Speak to Krennan Aranas to take part in the battle for Gilneas City.", sourceObjective = "Achieve victory in the Battle for Gilneas City.", progress = "No...", completion = "We've driven the Forsaken back.  We hold three out of the four districts.\n\nBut at what cost...", sourceObjectiveStatus = "unverified-source-field" }
quests[24905] = { id = 24905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returning a Favor", description = "You know, while you were out doin' your thing, Megs stopped by here. I hadn't seen her in months, but she barely gave me the time of day, just wanted me to tell you she had more business lined up.\n\nShe said she was headed over to the Dunemaul Compound to set up shop, something about ogres. Since you're done here, might as well head over...I woundn't keep a goblin like her waiting.", sourceObjective = "Find Megs Dreadshredder at the Dunemaul Camp.", completion = "I've got a great one for you this time, {name}. We're gonna initiate these ogres into the Horde...working directly under us.", sourceObjectiveStatus = "unverified-source-field" }
quests[24906] = { id = 24906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seaside Salvage", description = "We've got to get goods moving in this market ASAP if we want to be competitive. I've got an angle for us.\n\nGadgetzan's under blockade by pirates, but plenty of the goods that get blown off the ships survive intact... they just wash away. Most of them wash up in the shallows just south of town.\n\nHead down there and start salvaging; there's crates full of pure profit just floating around down there.", sourceObjective = "Collect 7 Steamwheedle Supplies.", progress = "Let's see what you've got.", completion = "Hmm, mostly usable. This is good stuff. I've already got buyers lined up, of course.\n\nHere's your advance for the rest of the work you're gonna do for me and the Bilgewater Cartel...partner.", sourceObjectiveStatus = "unverified-source-field" }
quests[24907] = { id = 24907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Puddle Stomping", description = "Here's the situation. If we want to establish the Bilgewater Cartel's market presence in Gadgetzan, we'll need to start providing services to the community.\n\nThe new coast has been great for business here, but the sea also brought sea giants with it. They're large, foul, and drive real estate values down.\n\nHead to the shallows just south of town and kill as many as you can, and I'll cut you in on some of the deals I'm brokering here.", sourceObjective = "Kill 8 Tidal Striders.", completion = "Property values have already gone up since you left. People like seafront views that don't include briny, gnarled giants stomping around.\n\nHere's your cut, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24910] = { id = 24910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocket Rescue", description = "Alright, {name}. We've done enough small jobs around here; it's time to seal the deal.\n\nThe ruins of Steamwheedle Port are still full of hapless Steamwheedle goblins, waiting to be rescued. Every single one of them is a potential future customer. They're firing on every boat that leaves port...so I say we take to the skies!\n\nThere's a hot air balloon just outside of town near the docks, we can use that. Go ahead and hop in, I'll catch up with you.", sourceObjective = "Deliver Life-Rockets to 5 Steamwheedle Survivors and use bombs to kill 40 Southshore Blockaders.", progress = "What's with the premature bail-out? We gotta get back out there.", completion = "Isn't it nice when you can do a good deed, and see enormous future financial gains from it? It warms my little goblin heart. And my big goblin wallet.\n\nYou did great, kid. Gadgetzan's gonna be ours soon. Here's a little token of my appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[24911] = { id = 24911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tropical Paradise Beckons", description = "Hey, you look like a discriminating adventurer.  Are you looking for something different?  Something exotic?  Something... profitable?\n\nWell shake the sand out of your boots, because I've got a proposition for you.  Williden Marshal is looking for competent sellswords such as yourself.  He's set up camp at Marshal's Stand, just southeast of the volcano in the center of lush Un'Goro Crater.\n\nThen again, paradise isn't for everyone, {race}.  It's up to you.  Your tropical oasis awaits.", sourceObjective = "Report to Williden Marshal at Marshal's Stand in Un'Goro Crater.", completion = "Hey Hol'anyee, look at the getup on this one!\n\n<Williden turns to face you.>\n\nAhem.  Our recruiter sent you?  Good.  Let's start out with a bit of honesty: Un'Goro isn't the perfect nirvana that you may have been promised.  You've probably figured that out on the way over here, though.\n\nShall we get to work?", sourceObjectiveStatus = "unverified-source-field" }
quests[24912] = { id = 24912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empowerment", progress = "<Highlord Darion Mograine speaks to you purposefully.>\n\nShadow's Edge is prepared to receive its final endowment of power.\n\nThe time has come to attempt the forging of Shadowmourne!", completion = "Stand Clear, {class}, and steady yourself." }
quests[24913] = { id = 24913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remember the Light", description = "Magtoor grows weaker by the second, {name}. My remedy is prepared... it must work. It must!\n\nYou have done so much for the both of us. I would be honored if you stayed for what may be Magtoor's final moments.", sourceObjective = "Help Anchorite Avuun say farewell to Magtoor.", completion = "I am moved, {name}. Prophet Velen has been in closely guarded seclusion. He has dared not waste his energy on anything save preparing for the final confrontation he has foretold.\n\nAnd yet, he came here, in person, to comfort a single dying soul.\n\nI must thank you as well, for helping me make my last effort to comfort my friend. My research will continue... and I hope that Magtoor will continue to watch over me.", sourceObjectiveStatus = "unverified-source-field" }
quests[24914] = { id = 24914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Personal Property", description = "You can detect no hinges or openings on this box. Were it not for the shifting of items inside, it could easily be mistaken for solid metal.\n\nIf anyone could know the method of its opening, it would be Highlord Mograine.", sourceObjective = "Bring the Sealed Chest to Highlord Darion Mograine in Icecrown Citadel.\n\nProvided item:", completion = "<After tracing a complex pattern of runes on each of the box's surfaces, the outline of a lid appears and a click echoes through the chamber.>\n\nHere you are, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24915] = { id = 24915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mograine's Reunion", progress = "What is that you hold, {class}?\n\nIt calls out to me, stirring feelings I thought to be long dead.", completion = "Impossible...\n\nFather, is it you?!\n\nYou have done me a great service, hero. I offer you the reins of my faithful steed. Do with it as you please, but do not forget those that assisted you in this monumental feat." }
quests[24916] = { id = 24916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jaina's Locket", progress = "Yes, {class}? How can I assist you?", completion = "What... how did you manage to come by this!?\n\nYou have done me a great service, hero. My heart could not bear to keep this locket, but I will place an enchantment upon it that you may find useful. Do with it as you please, but do not forget those that assisted you in this monumental feat." }
quests[24917] = { id = 24917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muradin's Lament", progress = "Whatdya got there, {race}?", completion = "Aye. I know this blade... and I will treasure it always - a moment of time that will be lost forever.\n\nYou have done me a great service, hero. I offer you a gift from the Frostborn dwarves. Do with it as you please, but do not forget those that assisted you in this monumental feat." }
quests[24918] = { id = 24918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sylvanas' Vengeance", progress = "What is it, {race}?", completion = "<Sylvanas silently reflects for a moment before returning her gaze to you.>\n\nYou have done me a great service, hero. I offer you the boon of the Banshee Queen. Do with it as you please, but do not forget those that assisted you in this monumental feat." }
quests[24919] = { id = 24919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lightbringer's Redemption", progress = "How may I be of service, {race}?", completion = "<Uther stares at the medal, speechless for a moment.>\n\nArthas' medal.\n\nI remember well the day I presented it to him...\n\nYou have done me a great service, hero. My soul may now rest in peace. I offer you a memory lost in time. Do with it as you please, but do not forget those that assisted you in this monumental feat." }
quests[24920] = { id = 24920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slowing the Inevitable", description = "As much as I want to exact swift and brutal revenge... I must honor my son's memory first.  He cared for his people first and foremost.\n\nThe Undertaker's Pass goes underground below Northgate River.  You must prevent the plague from being deployed while we evacuate our men, women and children to Aderic's Repose.\n\nWe captured one of the Forsaken's dreaded bombing bats.  I want you to fly the infernal beast as best you can and unleash hell upon those who seek to bring the Plague to our people.  Hurry!", sourceObjective = "Use the Captured Riding Bat to destroy 6 Forsaken Catapults and 40 Invading Forsaken.", progress = "Is it done, {name}?", completion = "You've done well, {name}.  Almost everybody managed to make it through.", sourceObjectiveStatus = "unverified-source-field" }
quests[24921] = { id = 24921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Aubrey", description = "You there! Fresh off the boat? Welcome to Kalimdor, a land hellbent to kill you or die tryin'.\n\nThere's trouble at the hold - as I'm sure you noticed on your way in. Admiral Aubrey needs all hands on deck if we're to make it through this. Consider yourself drafted, {class}!\n\nFollow the road up the hill and you'll find Aubrey in the tower, topside.", sourceObjective = "Report to Admiral Aubrey in Northwatch Hold.", completion = "Hm? What unit are you with, {class}?\n\nNo matter, we need all hands. My fleet is in tatters and they've broken into the hold. You armed? That's good enough for me.", sourceObjectiveStatus = "unverified-source-field" }
quests[24922] = { id = 24922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Classic Random Heroic (1st)" }
quests[24923] = { id = 24923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Crusade Random Heroic (Nth)" }
quests[24924] = { id = 24924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oomlot Village", description = "The pygmies took most of our people back to their village. Who knows what evil they're up to?\n\n{name}, you have to go up there and free all of the captives before the pygmies work their voodoo on them!\n\nIzzy's already up near Oomlot Village to the southeast. She'll give you the heads-up on what's going down.\n\nYour pygmy helmet looks like it's in bad shape, but it should last long enough for you to get there.\n\nI hope.", sourceObjective = "Speak with Izzy at Oomlot Village on the Lost Isles.", completion = "{name}? What are you doing wearing that pygmy helm? Looks like it's about to fall apart.\n\nI'm glad that they sent you up here. I thought for sure they were going to send that jerk, Grapplehammer and his ego-enabling assistant.", sourceObjectiveStatus = "unverified-source-field" }
quests[24925] = { id = 24925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free the Captives", description = "They've got a bunch of our people in there. I know that they're doing strange rituals to them. It looks like they're sucking the life force right out of them!\n\nYou have to go into the village and free the captives before it's too late!", sourceObjective = "Free 5 Goblin Captives.", completion = "Great job, but that's not even half of the hostages that they took from town.\n\nDarn it all! They must have taken the rest of the captives to their other villages up in the volcano!", sourceObjectiveStatus = "unverified-source-field" }
quests[24926] = { id = 24926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Serving A-Me 01", description = "Greetings.  I unit A-Me 01.  You... {race}?\n\nA-Me's mission to study the local gorillas was success.  A-Me has gathered data that Karna needs.\n\nA-Me 01 not returning, though.  A-Me has new family now.  Here, with the gorillas, A-Me stay.\n\n<A-Me 01 detaches a small device from her hand and gives it to you.>\n\nYou bring data back to Karna.  You tell her what happen.", sourceObjective = "Bring A-Me's Thumb Drive back to Karna Remtravel at Mossy Pile in Un'Goro Crater.", progress = "Wh... what's this?", completion = "She decided to stay?  Fascinating... I'll have to look over this data and find out why.\n\nThank you again, {name}. I really appreciate it.", sourceObjectiveStatus = "unverified-source-field" }
quests[24927] = { id = 24927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead Man's Chest", description = "Look, babe, you should be able to see what's happening here pretty easily. There's pirates, there's goblins, the goblins are fighting the pirates. There's some sad little gnomes trying to fight the pirates too.\n\nI'll make it nice and simple for you: we need to kill a lot of pirates. Go do that, 'kay? We don't want the gnomes killing more than us, after all.", sourceObjective = "Kill 15 Southsea Freebooters of any kind.", progress = "Look, if you think the bare minimum is enough, then ok. But some people choose to kill more pirates and I encourage that, ok?\n\nAnd by \"ok\", I mean \"go kill more and stop wasting my time\".", completion = "I'm pleased to report that our brand recognition in this area has skyrocketed now that you've killed most of the people who didn't want us here.", sourceObjectiveStatus = "unverified-source-field" }
quests[24928] = { id = 24928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To The Ground!", description = "I've conducted a thorough appraisal of the real estate here and, unfortunately, its market value is just far too low to be of any use. We're going to have to renovate.\n\nLuckily for you, I've learned a few things about arson. Hopefully you have too! You're going to be throwing these perfectly safe bottles of flaming rum at those filthy ramshackle huts over there.\n\nTry not to stand downwind.", sourceObjective = "Set fire to the Northwest Shack, the Southeast Shack, and the Northeast Shack.", completion = "Wonderful job. Have you ever thought about becoming a full-time arsonist? I know a few people, it's a nice gig.\n\nWell, we'll chit-chat about that one later. More to do here!", sourceObjectiveStatus = "unverified-source-field" }
quests[24929] = { id = 24929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Send a Message", description = "The Oomlot leader, Yngwie, is too powerful to be left alive. He's barking nonsense from the raised west side of the village, across the rope bridge.\n\nGo up there and get him before he sends the rest of the village against us.\n\nPiece of cake!", sourceObjective = "Slay Yngwie.", completion = "Nice work, bud! Hope he wasn't too tough.", sourceObjectiveStatus = "unverified-source-field" }
quests[24930] = { id = 24930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "While You're At It", description = "Fine by me if King Greymane wants you to risk your life to rescue a known traitor.\n\nDo me a favor and do something useful while you're out there and kill these cursed fleabags.", sourceObjective = "Kill 5 Bloodfang Worgen.", progress = "What is it then, {name}?", completion = "If I hadn't seen you kill a few of the mangy things with my own eyes, I'd think you did not complete the task I asked of you.\n\nIt looks like we're hardly putting a dent in their numbers.", sourceObjectiveStatus = "unverified-source-field" }
quests[24931] = { id = 24931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gazer Tag", description = "You're going out to hunt hyenas, eh? If you don't mind, I've got an offer myself. I'm in need of eyes from the Glasshide Gazers that lurk to the north. Their eyes contain wonderful crystals, valuable to...collectors.\n\nNow, you may have heard that some sad individuals use these to enhance paramental abilities, but I assure you, my interests are purely academic!\n\nBring me a good portion of them and I'll pay you well for them. Better than these copper-pinching goblins will, at least!", sourceObjective = "Collect 5 Ocular Crystals from Glasshide Gazers.", progress = "Do, ah, do you have them?", completion = "Ahh, perfect! Just what I need...full of potent focusing energies...\n\n...ahem! I mean, perfect for my collection! Narain Soothfancy is in no need of artificial enhancement of any kind!\n\nNow take your pay and be off!", sourceObjectiveStatus = "unverified-source-field" }
quests[24932] = { id = 24932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting Losses", description = "I've spent the last week starin' at this ugly pit trying to think of how to exploit a bunch of dangerous, violent arthropods for profit. Now I'm out of ideas, and starving.\n\nThese things are a wash, and I say it's time to start clearing them out. Head down into that pit and start killin' bugs.", sourceObjective = "Kill 15 Hazzali Silithid of any kind in the Gaping Chasm.", completion = "This isn't goin' fast enough. There's gotta be a faster way...", sourceObjectiveStatus = "unverified-source-field" }
quests[24933] = { id = 24933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chicken of the Desert", description = "I've got an idea, but we're going to need bait.\n\nThe other day I saw a rabid blisterpaw hyena wander too close to the edge of the chasm, and one of the silithid comes diving out of nowhere. Nearly swallowed it whole! Horrible sight.\n\nSo we're gonna need hyena meat, obviously. Go gather some, make sure it's fresh, and bring it back here. There should be plenty just north of the camp.", sourceObjective = "Collect 6 pieces of Hyena Meat.", progress = "This is fresh, right? They won't go after anything that's been withering in the sun.", completion = "Man, this stuff looks delicious. I'm half tempted to just fry some up myself.\n\nNo! We've gotta focus on gettin' out of here.\n\nMaybe just one piece...", sourceObjectiveStatus = "unverified-source-field" }
quests[24934] = { id = 24934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repel Boarders!", description = "{name}, the sea is our only lifeline, and right now most of my fleet is either steaming back to Theramore for repairs or rusting at the bottom of this bay. Only the Blackpool remains afloat to defend our harbor.\n\nBut she's just signaled that she's being boarded!\n\nSpeak to me when you're ready, I'll have one of our naval gryphons deposit you right on the deck. Slaughter the rageroar sea dogs who dare assault my precious ship and report to Captain Fisher for further orders.", sourceObjective = "Speak to Admiral Aubrey to fly to the Blackpool and kill 6 Rageroar Sea Dogs.", progress = "Blood! All over my freshly polished brass.", completion = "You make a hell of a marine, {name}.\n\nWe'll mop up the others. But it looks like the Horde fleet is disengaging - maybe to land more troops ashore?\n\nAdmiral Aubrey will know what to do. Talk to me when you're ready to fly back!", sourceObjectiveStatus = "unverified-source-field" }
quests[24937] = { id = 24937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oomlot Dealt With", description = "{name}, you have to get back to the Town-In-A-Box and warn them about the goblin zombies up in the volcano's caldera!", sourceObjective = "Speak with Sassy Hardwrench at the Town-In-A-Box on the Lost Isles.", completion = "They turned some of our people into zombies? Tell me something I don't know....", sourceObjectiveStatus = "unverified-source-field" }
quests[24938] = { id = 24938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Guns of Northwatch", description = "Captain Fisher signaled us from below. The Horde fleet is landing shore parties? We can't let them flank us from the beach.\n\nI've already sent two of my best gunners down there to defend the beach head. Talk to Cannoneer Smythe down on the shore.\n\nYou'll have to fight your way through the courtyard to get there. See if you can help the others secure the hold on your way down!", sourceObjective = "Speak with Cannoneer Smythe.", completion = "Aubrey sent you? Good! I take it you know your way around a cannon?", sourceObjectiveStatus = "unverified-source-field" }
quests[24939] = { id = 24939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Run Out the Guns", description = "We've got the hardware but not the manpower, {name}. Man one of the carronades on the shore here and take out those incoming boats!", sourceObjective = "Use a Northwatch Shore Battery to destroy 10 Rageroar Rowboats.", completion = "Ho ho! The beach is ours!\n\nWe just might keep a foothold on this miserable dustball of a continent after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[24940] = { id = 24940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up the Volcano", description = "A whole bunch of our people headed up to the top of the volcano to mount a counter-offensive. There's something horrible brewing up there on the Lost Peak.\n\nThey're waiting for you before they make any moves against the pygmies. Those evil little things turned a lot of us into zombies!\n\n{name}, save us!", sourceObjective = "Speak with Coach Crosscheck at the Lost Peak on the Lost Isles.", completion = "My star player has arrived!", sourceObjectiveStatus = "unverified-source-field" }
quests[24941] = { id = 24941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Langridge Shot", description = "{class}! Thank the light - they've practically driven us back to the docks. The courtyard is overrun!\n\nWe're out of canister shot and the orcs are getting ready for an assault up the hill. We need to improvise some scatter-shot, and fast.\n\nHurry, run into the broken tower here and grab whatever sharp, pointy bits of scrap metal you can lay your hands on. Knives, forks, nails - anything! Load the cannon when you've got an armful!", sourceObjective = "Gather 15 pieces of Langridge Shot.", progress = "Paxton has already loaded a charge into the cannon. All it needs is the ammunition you improvised.", completion = "The Horde is massing at the base of the hill. Breathlessly, you stuff the debris you collected into the muzzle of the cannon, step back, cover one ear, and tug on the igniter cord...", sourceObjectiveStatus = "unverified-source-field" }
quests[24942] = { id = 24942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zombies vs. Super Booster Rocket Boots", description = "Those zombies that got past us are nothing compared to the numbers waiting just through the pass. If we don't deal with them soon, the pygmy witch doctors are going to send all of them against the town, and even the cannons down there won't be able to handle that many!\n\nI brought a couple of shredder boots along. Greely modded them and now they're Super Booster Rocket Boots!\n\nUse the boots to incinerate the zombies in the Oostan villages to the east.", sourceObjective = "Use the Super Booster Rocket Boots to slay 50 Goblin Zombies.", progress = "You still have a few {race} zombies to deal with, {name}. Look sharp, superstar!", completion = "You did it! No more zombies to worry about. Let's pause a moment in silence for the stinky departed.\n\nOkay, done.", sourceObjectiveStatus = "unverified-source-field" }
quests[24943] = { id = 24943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Re-Take the Courtyard", description = "That's one way to clear a hill. Those corpses are impaled with knives and forks!\n\nThe Rageroar clan has breached the walls, but we can still turn this fight around. Go down the hill and help our men hold on to the courtyard below...", sourceObjective = "Kill 10 Rageroar Grunts.", completion = "Great work! We've knocked them on their heels, maybe long enough to shore up our defenses.\n\nProvided we find a way to take out their artillery...", sourceObjectiveStatus = "unverified-source-field" }
quests[24944] = { id = 24944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back in the Fight", description = "This fight isn't over, {class}. Not by a long shot.\n\nSome of the soldiers in the courtyard still have breath in their lungs. We can save them! I've soaked these rags in an herbal remedy we used to rely on back in Gilneas. The smell is awful but this poultice can practically raise the dead.\n\nUse these bandages on wounded defenders down in the courtyard and we'll see if we can't get them back in the fight.", sourceObjective = "Use the Herb-Soaked Bandages on 6 Wounded Defenders.", progress = "I hope you have enough bandages. My supply of those herbs was cut off when these brutes sacked my beloved Gilneas.", completion = "A steady stream of the walking wounded have come up the hill to see me, {name}. I trust that was your work? Well done!", sourceObjectiveStatus = "unverified-source-field" }
quests[24945] = { id = 24945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Three Little Pygmies", description = "Look, I think it's great that we're destroying all of these zombies, even though they're our friends and family. But don't you think we should be taking care of the pygmies that are creating them as well?\n\nAt the three Oostan villages, Nord, Sor, and Ost, there are witch doctors: Gaahl, Malmo, and Teloch.\n\nMaybe you could take care of them? I don't want to be turned into a zombie!", sourceObjective = "Slay Gaahl, Malmo, and Teloch.", progress = "Um, boss, look, I don't know how to say this, but you might have missed one or two of those pygmy witch doctors.\n\nI'm just saying.", completion = "I gotta tell you, that's a load off of my mind. That is, I won't have to worry about no new zombies coming after my brains!", sourceObjectiveStatus = "unverified-source-field" }
quests[24946] = { id = 24946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rockin' Powder", description = "I'll give these pygmies one thing... they sure know how to party! But they're not so clever. I think I've discovered the source of their rockin' powers: Rockin' Powder!\n\nIt turns out that this stuff, which turns them into world-class rockers, is also highly explosive. We must have it!\n\nSo, while you're in there at Oostan to the east, make sure that you pickup a whole bunch of the stuff. Trust me, you're going to need it for what's coming up!", sourceObjective = "Collect 5 scoops of Rockin' Powder.", progress = "Hmm, let me see how much you've got.", completion = "This will do. In fact, it's more than we need. I devised an ingenious idea for a weapon that the boots will be turned into once you get them to Hobart.\n\nHand the powder over and I'll load it into the Super Booster Rocket Boots.", sourceObjectiveStatus = "unverified-source-field" }
quests[24947] = { id = 24947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Momentum", description = "We can't just rest on our laurels here, babe. We've got to keep this momentum going! People are talking about us.\n\nUnfortunately, they're also talking about this air-headed gnome, Kelsey, who's apparently been running jobs right alongside us. If we're going to drive her out of what's rightfully a goblin town, we need to seal the deal here.\n\nWe're going to take care of Gadgetzan's pirate problem for them, for good. Head south to Lost Rigger Cove, I'll meet you there.", sourceObjective = "Meet Megs Dreadshredder at Lost Rigger Cove.", completion = "Good thing you're here! I'm gonna need a lot of help if we want to beat these gnomes to the punch.", sourceObjectiveStatus = "unverified-source-field" }
quests[24948] = { id = 24948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lifting the Siege", description = "We'll never be able to re-secure the fortress walls so long as Rageroar and his goons have access to artillery. I need you to fight your way across that chasm and take out his big guns.\n\nOrcs season their heavy machinery with coal tar, which makes them flammable. Take my torch and burn any catapults you see north of Northwatch.\n\nThen, torch those big blade-throwers in Rageroar's base camp! Those things have killed enough of our men.", sourceObjective = "Use Paxton's Torch to burn 3 Rageroar Catapults and 1 Rageroar Blade Thrower.", progress = "Burn it all, {class}. Burn it to cinders!", completion = "Good! Without heavy equipment, the Horde will have to pull back to regroup. We've bought ourselves some time to re-secure the fortress. Well done!", sourceObjectiveStatus = "unverified-source-field" }
quests[24949] = { id = 24949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Booty Duty", description = "Let's not be wasteful here, babe. These pirates have tons of valuable nonsense just sitting around, waiting to be fenced. Can you believe they just sit on this stuff?\n\nI mean, why do they even bother taking it if it's just going to sit around? Stolen goods should be sold off and used to buy shiny new things.\n\nAnyway, be a dear and go grab as much of their loot as you can carry while you're out busting heads. Ciao!", sourceObjective = "Collect 10 pieces of Pirate Booty.", progress = "Let's see what you've got. You're not hiding any for yourself, are you? You'll never find a buyer without me, you know.", completion = "Beautiful! And to think these idiots were just sitting on it.\n\nHere's a bit up front, we'll talk about profit-sharing bonuses later.", sourceObjectiveStatus = "unverified-source-field" }
quests[24950] = { id = 24950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Dreadbeard", description = "Alright, babe, I've got something bigger for you to take on here.\n\nWe spotted the captain of the Southsea over on one of his boats to the south; that's to the south, and NOT the one we've been suicidally bum-rushing for the better part of several hours. He's sitting up there, smug and stoic, watching us war down here.\n\nI'll spare you the \"hostile takeover\" jokes. Get on his ship and beat the tar out of him, and we're done here!", sourceObjective = "Kill Captain Dreadbeard.", completion = "Sea giants? You think he was training them towards Gadgetzan on purpose?\n\nWhatever, he's splitsville now. And Gadgetzan owes us big time! I can't wait to see the look on Marin's face.\n\nHere's your cut, babe. You're moving up in the world.", sourceObjectiveStatus = "unverified-source-field" }
quests[24951] = { id = 24951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Great Idea", description = "Now that we've got a good pile of fresh chunks, we just tie it to this rope...and now you're ready to go catch me a silithid.\n\nWhat? Don't give me that look, it's perfectly safe. Well, mostly safe. Okay, you might die painfully. But it'll be easy! Just throw this meat out there, wait for a bug to pounce on it, and then drag 'em back here by the rope!\n\nGo after one of the swarmers. I haven't seen the other ones go for hyenas before, and you should find plenty of swarmers around the edge of the pit.", sourceObjective = "Use the Bootlegger Bug Bait to capture a Hazzali Swarmer.", progress = "I don't see any bug with you, pal.", completion = "Look at the size of it! It's glorious. This ugly sucker's gonna help us bring down the whole hive.", sourceObjectiveStatus = "unverified-source-field" }
quests[24952] = { id = 24952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocket Boot Boost", description = "You need to get those boots down into the caldera to Hobart Grapplehammer.\n\nNow that they're infused with the leftover rockin' powder, they should have enough thrust to get you all the way there on one shot.\n\nWhen you're ready, activate the boots. Don't worry, they're automatically set to land you safely.\n\nI think.", sourceObjective = "Use the Rockin' Powder Infused Rocket Boots and deliver them to Hobart Grapplehammer.", progress = "Well there you are!", completion = "There's no time to waste, boy!\n\nWhat's wrong with the actuator on the left boot?!", sourceObjectiveStatus = "unverified-source-field" }
quests[24953] = { id = 24953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Trying to Kill Some Bugs", description = "Now it's time for my plan to go into full effect. We've got the captured bug strapped up with as many explosives as it can carry, and with Soothfancy's mostly amazing mental powers, we're gonna drive that sucker straight down into the center of the underground hive.\n\nAnd then...BOOM! No more bugs!\n\nYou get the personal honor of directin' the ugly thing. Go talk to Narain and get set up with your bug-pal.", sourceObjective = "Talk to Narain Soothfancy to pilot the Mind-Controlled Swarmer into the Gaping Chasm hive.", progress = "I didn't hear no cave-ins, pal! Try again!", completion = "Oh man, that was awesome! You should've seen the flames coming out of the hive!\n\nHere's your reward, for entertaining me as much as for clearing the hive!", sourceObjectiveStatus = "unverified-source-field" }
quests[24954] = { id = 24954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Children of a Turtle God", description = "Volcanoth is the turtle god in the cave that these primitives worship.\n\nIt's not really a god.\n\n<Hobart rolls his eyes.>\n\nBut it is tough enough that I'm going to have to devise a new weapon for you from the one functioning boot we have left.\n\nI think that the age-old motto of \"fight fire with fire\" applies here. Plus, I like fire!\n\nLet's get some fire glands from Volcanoth's children. That should give me time to modify the rocket boot into something more fitting.", sourceObjective = "Collect 5 Fire Glands.", progress = "No time like the present to be done with the simple task I put before you, {name}. Wouldn't you agree?", completion = "Careful with those glands, {name}, careful!\n\n\n\nAnd now to load them into the refashioned shredder boot. I'm certain that you'll be surprised and amazed by my genius invention.", sourceObjectiveStatus = "unverified-source-field" }
quests[24955] = { id = 24955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Un-Chartered", description = "As I may have mentioned, I'm trying to get these Dunemaul ogres to join the Horde..and  work for the Bilgewater Cartel as cheap local labor.\n\nTo pull this off, we've gotta pay lip service to the actual initiation process and all that, or I'm going to catch flak later on. So I've gotten this charter drawn up, and slapped the initiation rites onto our own limited time offer labor stipulation contract.\n\nI've got a disguise for you here, so suit up and get all these signatures filled out.", sourceObjective = "Obtain 10 Charter Signatures from Dunemaul Ogres.", completion = "Wow, nice work! I'm amazed you even got them to hold a pen without eating it.\n\nYou can uh, just throw the suit over there. Away from me. In the fire.", sourceObjectiveStatus = "unverified-source-field" }
quests[24956] = { id = 24956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silencing Rageroar", description = "I have encountered the Rageroar clan before, {name}. They are led not by an orc, but by a monster - a war-gorged fiend without a shred of decency or compassion. He and his lieutenants must be killed, not just to save Northwatch, but for the good of all of Azeroth.\n\nKarga Rageroar wears a helm. Execute him, {class}, and bring the helm to me. It is of ... particular importance.\n\nRageroar has made his camp across the chasm, east of here.", sourceObjective = "Slay 4 Rageroar Lieutenants and acquire Rageroar's Helm by killing Karga Rageroar.", progress = "Is he dead? Do you have his ... helm?", completion = "<Tolliver grasps the helmet reverently with quivering hands.>\n\nRageroar's battleships intercepted our vessel as we fled from Gilneas. We were to be carried here as trophies to the Warchief. As we neared the shore, some of us fought back. Rageroar - he began killing indiscriminately - howling with laughter. Our ship capsized and he ordered his men to fire at us as we drowned. Few of us made it to land.\n\nAfterwards, I learned that he wore my brother's scalp as... as a trophy.\n\n<He closes his eyes.>", sourceObjectiveStatus = "unverified-source-field" }
quests[24957] = { id = 24957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get The Centipaarty Started", description = "Okay, babe. Like I said, the ogres are too dumb to know what signing that charter meant. Now we have to actually get them to come along with us, so we'll be procuring what is apparently beloved local flavor.\n\nBeloved local flavor for drooling idiots, I mean.\n\nJust pop on over to the Noxious Lair to the west, it's that big horrible pit full of dangerous silithid. Kill a bunch of the Centipaar silithid and bring back the pieces so we can hand 'em out, okay? Ciao.", sourceObjective = "Collect 20 Centipaarts from Centipaar Silithid.", progress = "Have you got enough? These ogres don't look like the type to like small portions.", completion = "Ugh! This entire camp is like a sampler course of awful smells.\n\nLet's not handle these things any longer than we have to.", sourceObjectiveStatus = "unverified-source-field" }
quests[24958] = { id = 24958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volcanoth!", description = "It took a lot of blood, sweat, and tears, but the Bootzooka, patent-pending, is ready for use!\n\nThese no-good pygmies have been feeding our people to their \"god\", Volcanoth, and they're about to unleash it on our town!\n\nYou have to get into the cave and kill that thing before it's too late!", sourceObjective = "Use the Bootzooka to slay Volcanoth.", completion = "I managed to get everyone else safely back to town.\n\nJump in, we gotta get out of here before the volcano blows for good!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[24959] = { id = 24959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fresh out of the Grave", description = "{name}!\n\nRise, {name}!\n\nWelcome back to the realm of the living.  With the blessing and power of the Dark Lady, I have freed you from death's grip.\n\nYou are no slave, {name}.  You are free to follow whatever path you choose from here.  If you choose to serve the Dark Lady Sylvanas, I recommend you speak with Undertaker Mordo.  You will find him behind me, in the graveyard.", sourceObjective = "Report to Undertaker Mordo at the Deathknell Graves in Tirisfal Glades.", completion = "Hello there.  You must be... {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[24960] = { id = 24960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wakening", description = "King, peasant, or {class}... I don't care WHAT you were before.  I just need somebody with a working tongue.\n\nBeing raised from the dead is strenuous.  Not everyone copes with it as well as you did.  In particular, there are three newly-raised undead who are having trouble coping right now.\n\nI want you to find them and talk to them.  It might be that they just need someone that they can relate with.\n\nYou'll find them here in the graveyard.", sourceObjective = "Speak with Marshal Redpath, Lilian Voss, and Valdred Moray.", progress = "No dilly-dallying now.  You're among the Forsaken now, and we hold ours to a higher standard.", completion = "You've done well, {class}.  As you can see, not all of us have resigned to our fates.  I'm glad to see that you're at least willing to work.\n\nValdred will be a valuable asset to the Forsaken.  As for the other two... there is not much we can do.  We cannot force them to join us.", sourceObjectiveStatus = "unverified-source-field" }
quests[24961] = { id = 24961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Truth of the Grave", description = "Earlier on, I saw a young Forsaken woman running towards the old inn.  She was screaming for her life, pleading to be taken back home.\n\nNot all of us are as resolute as others, {name}.  Even so, we must accept our fate as undead if we are to rise up against those that would put us down.\n\nTake my hand mirror and show it to the young woman.  She needs to see what she really is, and join us in our cause.  Besides... we can use all the bodies that we can get.", sourceObjective = "Find Lilian Voss inside the large inn in Deathknell. Then speak with her to show her Elreth's Hand Mirror.", progress = "Have you spoken with her yet?  She needs to be shown the truth.", completion = "You say she ran away?  What a shame.\n\nVery well.  As long as she's maintained her free will, there's still hope.", sourceObjectiveStatus = "unverified-source-field" }
quests[24962] = { id = 24962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trail-Worn Scroll", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the hunter trainer Xavier. I would take some time to read it before heading out again.", sourceObjective = "Read the Trail-Worn Scroll and speak to Xavier the Huntsman in Deathknell.", progress = "Ah, so you've arrived. Good. I overheard that a few others were able to escape \"death\" and were heading into town. Perhaps that resilience will pay off in the future also.\n\nYou may thank Sylvanas for your freedom... freedom of mind and body. Though you still remain tortured by the plague and its effects, you are now free to come and go as you see fit.", completion = "I will be here to train you as you grow in experience... find me as often as you like. I charge a minimal fee, but you'll find everything I can teach you to be worthwhile.\n\nGo now and test your skill. Many more things will become known to you as you gain experience, some of which I am unable to discuss with you here. Just know that Sylvanas will need hunters with your type of cunning in the future.\n\nYou will be the backbone of our salvation. Do not forget it.", sourceObjectiveStatus = "unverified-source-field" }
quests[24963] = { id = 24963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maul 'Em With Kindness", description = "Okay, babe, listen up. There's two ways to get people to do what you want. You can provide goods, services, and things people want...or you can beat the living daylights out of them.\n\nI've often found it's useful to do both at the same time, and you're pretty familiar with both methods by now. Take these little silithid treats, go and beat some ogres dizzy, and then give them the treat before you knock them completely dead, 'kay?", sourceObjective = "Use the Bilgewater Cartel Promotional Delicacy Morsels on 8 Dunemaul Ogres after weakening them.", completion = "Good job, you've taught half the ogres here to fear and respect anything vaguely {race}-shaped.\n\nIt's amazing what a little reward will do to keep people under your thumb, isn't it? Here's your payment, by the way.\n\n...what's with that look?", sourceObjectiveStatus = "unverified-source-field" }
quests[24964] = { id = 24964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thrill of the Hunt", description = "I've been told that I'm supposed to train you how to be a hunter.  That's all well and good, but in my opinion, you'll get more training out in the field than you will talking about theories with me.\n\nI suppose I can show you a couple of my tricks.  Here, come take a look at this...", sourceObjective = "Learn Steady Shot from Xavier the Huntsman in Deathknell, then practice using Steady Shot 5 times on a Training Dummy.", progress = "There'll be time for idle chat later, {name}.  For now, we must train.", completion = "You seem to be somewhat of a natural, {name}.  This is good.  I can't teach you everything myself.\n\nGo, practice what we've discussed today.  Return when you're stronger, and we'll cover some more tricks and abilities.", sourceObjectiveStatus = "unverified-source-field" }
quests[24965] = { id = 24965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magic Training", description = "Let's get some work done, shall we?  I've got a new spell for you.  You interested?\n\nThis spell won't work like anything you've previously learned. Each time you cast another spell, there's a chance you'll have an opening to cast Arcane Missiles.", sourceObjective = "Learn Arcane Missiles from Isabella in Deathknell, then practice using Arcane Missiles 2 times against a Training Dummy.", progress = "What's the matter... did you run out of money?", completion = "I've got to admit, the spell I just taught you probably won't increase your intellect severalfold.  That was a lie to get you to buy my services.  But it will still be a helpful spell for you and your allies.\n\nNo hard feelings!", sourceObjectiveStatus = "unverified-source-field" }
quests[24966] = { id = 24966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Light and Shadows", description = "A Forsaken priest is a curious beast,\n<his/her> path an unusual course.\n$G His: Her; shadowy rites cannot come from the Light, so <he/she> seeks a more sinister source.\n\nNot only has the world forsaken us, {name}... it seems the Light has left us as well.  As the poem hints, however... we are not without power.\n\nFirst, I shall teach you a fast heal to repair damage.  Speak with me again, and I will share with you the word's proper incantation.", sourceObjective = "Train Flash Heal from Dark Cleric Duesten in Deathknell. Then, practice casting Flash Heal 5 times on Wounded Deathguards.", completion = "You're a good student, {name}.  You'll go far.  If you ever need any further training, return to me and I'll happily oblige.", sourceObjectiveStatus = "unverified-source-field" }
quests[24967] = { id = 24967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stab!", description = "Quiet down!  I don't want these novices around us to hear what we're about to discuss.\n\nListen up... {name}, is it?  I've got a technique that'll change the way you operate as a rogue.  You'll be able to follow up on your attacks with a deadly finishing move. Maybe even slide a dagger between their vertebrae.  Interested?", sourceObjective = "Learn Eviscerate from David Trias in Deathknell, then practice using Eviscerate 3 times on a Training Dummy.", progress = "Shh!  Quiet down!", completion = "Trust me, this'll be worth the money.  And hey - if you need any more training, stop by any time.", sourceObjectiveStatus = "unverified-source-field" }
quests[24968] = { id = 24968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Deeds", description = "As you continue your career as a warlock, you'll find it helpful to keep your spellbook filled with the latest incantations.  Lucky for you, I know these spells, and I'm willing to train you... for a price.", sourceObjective = "Learn Immolate from Maximillion in Deathknell, then practice casting Immolate 5 times on a Training Dummy.", progress = "Are you not interested in training?", completion = "Congratulations... you're one step closer to being a master of the dark arts.  Go practice a bit, and return when you're stronger.  I'll have more to teach you then.", sourceObjectiveStatus = "unverified-source-field" }
quests[24969] = { id = 24969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charging into Battle", description = "If you want to become a stronger warrior, you'll need to work on your weapons.  You'll find stronger swords and larger shields out on your adventures, that I have no doubt about.  However, as a warrior you also shouldn't forget your legs. \n\nTrain with me, {name}, and I'll show you how to move quickly around the battlefield.  You care to learn?", sourceObjective = "Learn Charge from Dannal Stern in Deathknell, then practice using Charge on a Training Dummy.", progress = "We will continue only once you have learned the art of the charge.", completion = "You have the makings of a great {class}, {name}.  Go, practice what we've discussed, and return when you are stronger.  Then I may have more to teach you.", sourceObjectiveStatus = "unverified-source-field" }
quests[24970] = { id = 24970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Better Than the Zombies", description = "While you were inside that cave, your big friend Darnell came by with some alarming news.\n\nSince the val'kyr arrived, we've seen more and more undead that chose not to join our forces under the banner of the Dark Lady.  They've been gathering at a small camp here in the valley, and now they've organized forces.\n\nThey plan to attack Deathknell, {class}.\n\nDarnell is just down the road, to the east.  Be careful, {name}.  While those undead aren't completely brainless, they're still not quite right in the head.", sourceObjective = "Report to Darnell at Deathknell in Tirisfal Glades.", completion = "{name}.  You made it.\n\nYou see those tents up there?  That's where we're headed.  The battle's probably already started.", sourceObjectiveStatus = "unverified-source-field" }
quests[24971] = { id = 24971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Rotbrain Encampment", description = "While you were taking care of matters for Executor Arren, I went off on an assignment of my own.  Shadow Priest Sarvis asked me to peek in on the Rotbrain camp.\n\nThere's a reason why they're called Rotbrains.\n\nTheir leader goes by the name of Marshal Redpath, and he's an absolute beast.\n\nLook, {name}... the attack is starting.  You're better in combat than I am.  Get in there and help out!\n\nWhen you're done, meet up with Shadow Priest Sarvis in the chapel.  Good luck, {name}.", sourceObjective = "Kill Marshal Redpath and 8 Rotbrain undead.", completion = "Being born again under the power of a val'kyr is a strenuous process.  Many don't survive the shock, turning into zombies or ghouls.\n\nOthers retain just enough humanity to seem normal on the outside... but they're sick inside.  We should have slain those rotbrains the day they were raised.\n\nAs for you... you're a strong {class}, {name}.  I knew you'd do well.  You'll be headed out of Deathknell soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[24972] = { id = 24972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vital Intelligence", description = "<Sarvis produces a piece of paper from within his robes.>\n\nThese will need to be taken to my field agent, Deathguard Simmer.  This information contains the whereabouts of the last few holdouts from the Scarlet Crusade.  We will destroy these crusaders, once and for all.  And I have a feeling you'll be instrumental in that effort, {name}.\n\nTake the road north out of Deathknell.  Soon after entering Tirisfal proper, you'll see a large manse.  Simmer's inside.", sourceObjective = "Deliver the Scarlet Crusade Documents to Deathguard Simmer at Calston Estate in Tirisfal Glades.", progress = "Yes, what do you want?", completion = "Yes, this is very good. You've done well in obtaining this information, {name}. Hmm... names of the Scarlet Crusade officers in the Tirisfal Glades...\n\nImagine the blow we could deal to the morale of those bloody zealots if we were to kill their leaders in one swift strike.  I will pass this information forward.", sourceObjectiveStatus = "unverified-source-field" }
quests[24973] = { id = 24973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Night Web's Hollow", description = "One of our greatest struggles is obtaining the natural resources we need to survive.  Gold was scarce in Lordaeron, even in the height of the Alliance's power so many years ago.\n\nThere is a gold mine to the west that has been overrun with spiders.  We need gold from the mine, but we can't very well get it while the spiders are crawling around in there.  I've not much manpower to commit to the task, so we'll just have to do it little by little.\n\nGet up there and see what you can do for us, {name}.", sourceObjective = "Kill 8 Young Night Web Spiders and 5 Night Web Spiders.", progress = "Be wary of the spiders' venom, {name}. If you feel a sharp burning, you may want to have it looked at.", completion = "Well, it's a start.  It'll take a few weeks or months to fully clean out the infestation.  After that, we'll have to get down there with some torches to burn away the webbing.\n\nYou've done your duty well, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24974] = { id = 24974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ever So Lonely", description = "You work hard your whole life, and what do you get?  Killed by a plague.  Then you work even harder in undeath, and what do you get?  Money, yes, and a small estate with a few pesky hangers-on, but happiness?  Not so much.\n\nI'm lonely in my old age, {name}.  I need a companion.  Use this leash on one of the murlocs at the Whispering Shore to the northwest.  You'll have to weaken it first before it can be leashed.  Then bring it back to me.", sourceObjective = "Use the Murloc Leash on a Vile Fin murloc at the Whispering Shore, then return it to Sedrick Calston at Calston Estate.", progress = "Oh, the pain of loneliness is too much to bear!", completion = "Oh, look at him!  Isn't he the most adorable thing you've ever seen?  Thank you, {name}.  I feel more energetic already.", sourceObjectiveStatus = "unverified-source-field" }
quests[24975] = { id = 24975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fields of Grief", description = "What have we here?  You look like a fledgling {class}.  If you hope to prove yourself to the Dark Lady, you need to learn the ways of the Forsaken.\n\nTo the west you'll find a farm.  Humans infest the land like mold on a rotting corpse.  And worse yet, the Scarlet Crusade patrols nearby from their tower.  Teach those scum a lesson and steal 10 of their precious pumpkins.\n\nOnce you have 10, bring them back to me.", sourceObjective = "Steal 10 pumpkins from the Solliden Farmstead in Tirisfal Glades.", progress = "Were you able to gather 10 pumpkins yet, {name}?", completion = "You have performed your bidding well, young {class}.  You are proving yourself to be quite an asset to the Dark Lady's army.", sourceObjectiveStatus = "unverified-source-field" }
quests[24976] = { id = 24976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Variety is the Spice of Death", description = "These pumpkins have a purpose, {class}.  They'll be the delivery mechanism for my latest batch of plague, which should be a particularly painful and virulent concoction.  However, the plague requires a few rare ingredients.\n\nWe'll need Marrowpetals, which grow at the bottom of Stillwater Pond, just to the east of here.  We'll also need Xavren's thorn, which grows on rocky cliffs to the northwest.  Finally, we need some briny sea cucumbers, found in the surf off of Whispering Shore.", sourceObjective = "Obtain 4 Marrowpetals, 4 Xavren's Thorns, and 8 Briny Sea Cucumbers.", progress = "I've got a feeling this will be my best batch yet, good {class}.", completion = "Excellent work, {name}.  Now comes the fun part.", sourceObjectiveStatus = "unverified-source-field" }
quests[24977] = { id = 24977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Johaan's Experiment", description = "Harmless pumpkins, right?  Or so it would seem.  If we are to defeat the Scourge advances from the North and the human infestation from the South we need to start realizing the full potential of our gift of undeath.\n\nWith a little ingenuity a simple pumpkin becomes an agent for our Dark Lady.  This pumpkin, laced with my latest formula, will prove to be quite a treat.\n\nYet another Scarlet Zealot has been captured and is being kept outside, by the gazebo.  Take this pumpkin to the fool.", sourceObjective = "Take the Laced Pumpkin to the Captured Scarlet Zealot at the gazebo at Calston Estate.", progress = "Stay away, foul and unholy creature!  May the Light protect me!  The Scarlet Crusade shall rid Azeroth of your...\n\n...oh wait.  Is that food for me?  I am so hungry...", completion = "By the Light!  Finally some food!  Sweet, sweet pumpkin....", sourceObjectiveStatus = "unverified-source-field" }
quests[24978] = { id = 24978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reaping the Reapers", description = "Humans are notoriously fickle creatures.  The farmers to the west are no exception.  Sure, they may be plowing their fields peacefully now, but tomorrow, they may be raising their scythes against us.  The Alliance looms close by in Gilneas, and the power of Stormwind looms to the south... any of these could recruit these tillers and use them as a wedge against us.\n\nI want them dead.  See to it that it's done.", sourceObjective = "Kill 10 Tirisfal Farmers or Tirisfal Farmhands.", completion = "You've the makings of a mighty {class}, {race}.  I heard the cries of those humans from all the way over here.  Perhaps soon we will be rid of this human blight.", sourceObjectiveStatus = "unverified-source-field" }
quests[24979] = { id = 24979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Scarlet Letter", description = "Lieutenant Gebler:\n\nHow curious that you would decide to take a prisoner... an undead one at that.  What were you thinking?  Do you think that, just because of the prisoner's former status, that she would be above the edicts of the Scarlet Crusade?\n\nThis is most troubling, Gebler.  I would remind you that there are penalties for such behavior.  I command you to execute the prisoner at once.  She is no longer one of us.", sourceObjective = "Find the prisoner in Scarlet Palisade.", progress = "A letter?  What does it say?", completion = "The Scarlet Crusade takes no prisoners.  That they would do so with this young woman... curious.\n\nThe powers that you describe are even more curious.  She passed through the bars of her prison and killed her captor?  Why hadn't she done that in the first place?", sourceObjectiveStatus = "unverified-source-field" }
quests[24980] = { id = 24980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scarlet Palisade", description = "We need someone with \"initiative\" like yourself to drive the Scarlet Crusade to the grave.\n\nProve to me you are capable of serving The Dark Lady by travelling west to the tower past the Solliden Farmstead and slaying 10 warriors of the Scarlet Crusade.", sourceObjective = "Kill 10 Scarlet Warriors.", completion = "Most excellent, {class}.  Your skill in the art of combat is undeniable.", sourceObjectiveStatus = "unverified-source-field" }
quests[24981] = { id = 24981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thorn in our Side", description = "Information we've received from Executor Arren in Deathknell contain all the details we need to wipe the human infestation from the lands.  According to the information, The Scarlet Crusade has assigned Captain Perrine and a brigade to the ruined tower southwest of Brill.\n\nKill 3 of his zealots and 3 of his missionaries.  And while you're there, see if you can dig up any other information about what they're up to.", sourceObjective = "Kill 3 Scarlet Zealots and 3 Scarlet Missionaries, and obtain the Scarlet Epistle.", progress = "We shall herd the Scarlet Crusade like cattle to their demise.", completion = "It sounds like we'll have to keep our eyes out for this Voss character.  I don't expect any Forsaken to receive a reward if we capture her... I'm just worried she'll eventually turn against us.", sourceObjectiveStatus = "unverified-source-field" }
quests[24982] = { id = 24982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Forsaken", description = "Speaking frankly, the Forsaken of yesteryear were a sniveling, pathetic group.  We huddled together in decrepit old human buildings, hiding from the Scourge, cowering from the Alliance, and groveling at the foot of the Horde.\n\nLook before you now, and see the product of the new Forsaken.  We have made our mark here on Azeroth, and that mark will grow.  Our dominion will soon blanket the world!\n\nYou want my advice?  Speak with Magistrate Sevren in Brill, down this road.  He runs that town.", sourceObjective = "Report to Magistrate Sevren at Brill in Tirisfal Glades.", completion = "Yes, I'm Brill's local magistrate, reporting directly to the Dark Lady.  Impress me, and you may end up meeting the Banshee Queen herself.  Now, onto your first task...", sourceObjectiveStatus = "unverified-source-field" }
quests[24983] = { id = 24983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forsaken Duties", description = "I need a fresh report from our Deathguard waystation to the east.\n\nI must know if more Scourge forces have slipped past The Bulwark and into Tirisfal.  Our vigilance on the border to the Plaguelands must be maintained - we can't let the Scourge get a stronger foothold here!\n\nTravel south along the road, then east at the fork to the waystation.  Speak with Deathguard Linnea.  She has the information I need.", sourceObjective = "Speak with Deathguard Linnea at Death's Watch Waystation in Tirisfal Glades.", completion = "Magistrate Sevren wants a report?  Very well: the defenders at The Bulwark are holding the majority of the Scourge at bay, but some do slip through on occasion.\n\nWe have seen sporadic Scourge activity east of this station, with a concentration around the Balnir Farmstead.", sourceObjectiveStatus = "unverified-source-field" }
quests[24988] = { id = 24988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chill of Death", description = "It's so cold, now.  The Plague of Undeath crawls through my veins like an icy serpent.  The mindless state will be upon me soon.  But no doomed destiny will prevent me from serving our Dark Lady.  When the call arose I sewed body bags for the fallen soldiers of Sylvanas's mighty army.\n\nNow my hands shake from the chill.  If you would bring me five duskbat pelts, I could sew myself a blanket.  Help me, {name}, so that I can continue to serve the cause.", sourceObjective = "Obtain five Duskbat Pelts.", progress = "Do you have five duskbat pelts yet, {name}?", completion = "I appreciate your efforts, {name}.  May Sylvanas recognize your bravery one day. . . .", sourceObjectiveStatus = "unverified-source-field" }
quests[24989] = { id = 24989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Magistrate", description = "You should return to Magistrate Sevren with the information I gave you.  He'll want it as soon as possible, so be swift.", sourceObjective = "Return to Magistrate Sevren in Brill.", completion = "It is troubling to hear of the Scourge slipping past the Bulwark.  Even now, they are ceaseless in their assaults.\n\nBut we will not give in.  The Lich King is dead; we will not be taken again!", sourceObjectiveStatus = "unverified-source-field" }
quests[24990] = { id = 24990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkhound Pounding", description = "Lady Sylvanas has called upon the Royal Apothecary Society.  She has challenged us to concoct a new plague, a plague deadlier than any ailment on Azeroth. This new disease will bring our enemies - living and dead - to ruin.\n\nMy studies show that the blood of beasts might prove to be the key. Here, fill these vials with darkhound blood so I can test my theory.", sourceObjective = "Collect 5 Vials of Darkhound Blood.", progress = "Have you collected the darkhound blood yet, {name}? Time is fleeting!", completion = "You have done well, {name} and I thank you for your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[24991] = { id = 24991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garren's Haunt", description = "As you're probably already realizing, the Royal Apothecary Society is a widespread organization.  We take our plague-alchemy seriously.  It is our belief that the more agents we have performing experiments, the sooner we will realize our objective.\n\nOne of our agents performs his work at a small encampment to the north of here.  His name is Jerrod, and he could use an apprentice of your... stature.", sourceObjective = "Report to Apothecary Jerrod at Garren's Haunt in Tirisfal Glades.", completion = "Holland?  He's an amateur.  You don't need a fancy two-story apothecarium to make plague... you need love.  And maybe some good assistants.\n\nLet me show you how plague is REALLY made.", sourceObjectiveStatus = "unverified-source-field" }
quests[24992] = { id = 24992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escaped From Gilneas", description = "As far as you know, a worgen rogue roaming in Tirisfal is a new development.  This is something that Executor Zygand would certainly be interested in.", sourceObjective = "Report the worgen's presence to Executor Zygand at Brill in Tirisfal Glades.As far as you know, a worgen rogue roaming in Tirisfal is a new development. This is something that Executor Zygand would certainly be interested in.", sourceObjectiveStatus = "unverified-source-field" }
quests[24994] = { id = 24994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doom Weed", description = "My envoy just delivered me a bushel of gloom weed.  Gloom weed!  I don't need gloom weed, I need doom weed!  You can see the predicament that I'm in, {name}.\n\nI'll make it worth your while to gather what I need. Bring back to me enough doom weed and I'll give you a suitable reward.\n\nIt is my understanding that they like to plague the flora near the mass gravesite, to the north of the Brill graveyard. Hurry and be mindful of the gnolls in the area.", sourceObjective = "Collect 10 Doom Weed.", progress = "<The apothecary mutters to himself.>\n\nThey brought me gloom weed?  GLOOM WEED?!", completion = "Ah, my doom weed. Excellent!\n\n<Apothecary Jerrod rubs his hands together greedily.>\n\nThese will come in quite handy. You've done me, uh, the Lady, a fine service today, {name}. As promised, here is the reward that you deserve.", sourceObjectiveStatus = "unverified-source-field" }
quests[24995] = { id = 24995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off the Scales", description = "While you were collecting samples for me, my experiments led me to realize that more reagents will be required for this new disease to spread properly.  Poisoning some hapless victim is child's play.  Plaguing an entire world proves to be a bit more complicated.\n\nI will need several scales from murlocs in the vicinity.  You will find the creatures ambling brainlessly along the coast to the north.", sourceObjective = "Obtain 5 Vile Fin Scales.", progress = "{name}, were you able to obtain those scales from the murlocs?", completion = "The scales are perfect, {name}. Exactly what I needed for this concoction.", sourceObjectiveStatus = "unverified-source-field" }
quests[24996] = { id = 24996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holland's Experiment", description = "I am to understand that another one of those foolish Dwarven Mountaineers has just been captured.  The deathguard has him stored here in this building, and they've assigned one of their own to persuade him not to escape.\n\nWhy don't you go see how the Captured Mountaineer enjoys this special drink I made for him?  It contains a subtle hint of what The Dark Lady has planned for the rest of Azeroth.", sourceObjective = "Bring Holland's Special Drink to the Captured Mountaineer.", progress = "Why if I had my trusted rifle you'd be as good as dead, {class}.  Just wait until the Steam Tank Brigade arrives to rescue me!", completion = "Ah, a drink at last.  What matter of ale is this?  I'm sure it's no Rhapsody Malt but I'll take anything to wet the old whistle at this point.", sourceObjectiveStatus = "unverified-source-field" }
quests[24997] = { id = 24997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Graverobbers", description = "The mass graves within the forest to the west of us were made to accommodate the... impressive... number of deaths Tirisfal suffered when the plague first came.  \n\nThe bodies in these graves have so far been spared an undeath, but the Scourge now send Rot Hide gnolls to gather the corpses and use them to bolster their armies.  This cannot be allowed!\n\nYour task is twofold: slay the Rot Hides at the mass grave and Garren's Haunt, and gather from them the embalming ichor that gives them life.", sourceObjective = "Kill Rot Hide Graverobbers and Rot Hide Mongrels, and obtain 6 flasks of Embalming Ichor.", progress = "Is your task complete?  Have you destroyed those dog-things and drained them of their ichor?", completion = "Expertly done, {name}.  The Scourge are mistaken if they think they can use those corpses against us, and the fluid you gathered from the Rot Hide slaves will be studied by my master.  It may have secrets we can use against them.", sourceObjectiveStatus = "unverified-source-field" }
quests[24998] = { id = 24998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maggot Eye", description = "Maggot Eye is a foul beast, even by gnoll standards.  He leads a band of renegade gnolls through the land, tearing up the glades and stealing whatever corpses he can find along the way.\n\nThose are our corpses!  We had plans for those!\n\nMaggot Eye resides just up the path from us.  Show him no mercy.  Mercy is for the weak.", sourceObjective = "Kill Maggot Eye and obtain his paw.", progress = "Yes?", completion = "Excellent work!  Now if only I can convince Jerrod to let us move our operation into that shack...", sourceObjectiveStatus = "unverified-source-field" }
quests[24999] = { id = 24999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Planting the Seed of Fear", description = "It seems that Jerrod has you hunting the murlocs to the north.  That's good... we can use their parts for our poisons.  I get a little worried sometimes, though...\n\nThe Vile Fin spawning grounds are not far off Tirisfal's northern coast, so you'll probably notice several tadpoles among the adults on the shore.  If these impressionable young murlocs were to seek revenge against us... that could ruin us.  Go chase them, and show them that the Forsaken and the Horde are not to be trifled with.", sourceObjective = "Chase 12 Vile Fin Tadpoles until they pass out in fear.", completion = "Did they run from you, {name}?  Good.  This is better than killing them... if they live to tell the tale, then future generations of murlocs will learn to fear us.", sourceObjectiveStatus = "unverified-source-field" }
quests[25000] = { id = 25000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teegan's People", description = "Hey, {class}!\n\nAre you headed to support Corporal Teegan? He's in charge of keeping the supply routes open.\n\nHe's got two of the most ornery dwarves I've ever met in charge of sundries. If you want to make an impression on those two crotchety hunters, you're going to need to show that you can hold your own against the predators around here.\n\nThe raptors west of the hold here are especially vicious. Bring Goucho some fresh hides and you'll make an impression while supplying the troops in one swoop.", sourceObjective = "Kill Terrortooth Runners and Terrortooth Scytheclaws to collect 8 Terrortooth Hides.", progress = "What is it, {class}? This here camp ain't fit for sight-seein'.", completion = "Hey, you're tougher than you look. These terrortooth hides reflect arrows and turn axe-blades - they don't go down easy, but their hides are worth their weight in silver in these light-forsaken Barrens. Nice work.", sourceObjectiveStatus = "unverified-source-field" }
quests[25001] = { id = 25001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandscraper", description = "My other assistants are making sure our proud new comrades are put into comfy cages and shipped to where they're needed most. For the Horde. Meanwhile, we've got one last item on our agenda.\n\nSandscraper, the chief of the Dunemaul Clan, is probably too dumb to even be aware of what we're doing here. But I absolutely loathe unfinished business, babe. He's lurking in the den just over there to the west. Knuckle down, take him out, and we'll be good to sign off on this, 'kay?", sourceObjective = "Kill Sandscraper.", completion = "And that's a wrap! Nothing left here for us but sand. Good job, babe.\n\nWell, maybe I shouldn't be so hasty. Did you find anything in that ogre den?", sourceObjectiveStatus = "unverified-source-field" }
quests[25002] = { id = 25002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scavenged", description = "<You discover a cargo manifest on the body, detailing a long list of sundries urgently needed on the front.>\n\n<A bloody trail in the dirt indicates bodies were dragged south of here, toward the raptor dens.>\n\n<The raptors may have dragged away the supplies, as well. Retrieving those supplies for Corporal Teegan could help salvage this disaster!>", sourceObjective = "Retrieve 10 Northwatch Supply Crates from the Raptor Den.", progress = "What? My supply caravan was sacked by those cold-blooded scissor-paw things?", completion = "My supplies! Well, that showed some real initiative, {class}. Those rap-saws or whatever they're called have torn lesser men to ribbons. Thank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[25003] = { id = 25003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Family Crypt", description = "The strongest point in the mills is the Agamand Family Crypt.  With necromancy, Captain Dargol has raised the ancestors of the Agamands and plans to use them against us.\n\nThis cannot pass, and you must stop it.  Travel to the Agamand Family Crypt and defeat the raised Agamand ancestors.", sourceObjective = "Kill 5 Wailing Ancestors and 5 Rotting Ancestors.", progress = "Time is not a luxury we have, {name}.  With each passing hour, the Scourge's hold on Tirisfal Glades grows more firm.", completion = "Your actions struck a telling blow against the Scourge.  And your victory will not go unnoticed - not by the Forsaken, nor by our enemies.\n\nContinue the struggle as we all do, {name}, and one day the Forsaken will have the dominion over Azeroth that they are owed!", sourceObjectiveStatus = "unverified-source-field" }
quests[25004] = { id = 25004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mills Overrun", description = "The Scourge are trying to form a base here at the Agamand Mills.  If they do, then they can stage further attacks within Tirisfal.\n\nThe orders have been given.  The Scourge in the Mills must be destroyed.\n\nCollect Notched Ribs from Rattlecage and Cracked Skull Soldiers, and Blackened Skulls from Darkeye Bonecasters.", sourceObjective = "Gather 5 Notched Ribs and 3 Blackened Skulls.", progress = "Our battles with the Scourge wage on, {name}.  Do your part and throw those cursed, mindless {race} back into the Plaguelands!", completion = "Your efforts are appreciated, {name}.  I will not thank you for doing what is necessary, but I will remember your name.", sourceObjectiveStatus = "unverified-source-field" }
quests[25005] = { id = 25005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Sevren", description = "I have destroyed the remains you've given me, {name}.  That is, all remains except for these...\n\nDevlin Agamand was weak and sharp-tongued in life, and was among the first to succumb to the plague.  He existed as a slave of the Scourge for a long time, longer than most.  As such, he may possess knowledge that would be of value to us.\n\nBring his remains to Magistrate Sevren, and tell him what I've told you.  He'll know what to do.", sourceObjective = "Speak with Magistrate Sevren at Brill in Tirisfal Glades.", progress = "The fetor of Scourge hangs about you, {name}.  What is it you seek?", completion = "Devlin Agamand?  Is that him you carry in your sack there?  Ha!\n\nYes, I know what Coleman wants to try, and I want to try it too.  I hope you're prepared, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25006] = { id = 25006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grasp Weakens", description = "While the Frozen Throne lies dormant, the grasp that the Lich King once held over the Scourge grows ever-weaker.  His grip on a weakling like Devlin Agamand should be weak enough that we can remove it entirely.\n\nSpeak with Shadow Priestess Malia in the manor on the east side of town.  She will assist you in the procedure.", sourceObjective = "Speak with Shadow Priestess Malia in Brill and participate in the extraction of Devlin Agamand.", progress = "What did you find out?", completion = "Ah, how unfortunate.  Perhaps the Scourge's dominion over Devlin's mind remained too strong.  Or perhaps our methods are simply not strong enough.  It's also possible that Devlin was too simple-minded to comprehend what we were asking him.", sourceObjectiveStatus = "unverified-source-field" }
quests[25007] = { id = 25007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "East... Always to the East", description = "You've done much for us here, {name}, but <men/women> of your caliber are needed elsewhere.\n\nTo the east lies the Bulwark: a fortified barricade against the ravages of the Plaguelands.  The Bulwark protects us from Scourge invasions, and has allowed us enough sanctity to build up our forces here in Tirisfal Glades.\n\nGo, speak with High Executor Derrington.  He is an ally, and will doubtless appreciate whatever aid you can give him.", sourceObjective = "Report to High Executor Derrington at the Bulwark in Tirisfal Glades.", completion = "<The High Executor sizes you up.>\n\nNot much of a {class}, are you?  Well, you will be when I'm done with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25008] = { id = 25008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filthy Animals", description = "You probably caught wind of some of them Hecklefang scavengers on the way in - they reek worse than ol' Durty Pete here. Worthless animals! They steal our kills, rummage through our supplies, and worse... they ain't good for eatin'.\n\nGo kill some.\n\nThen kill some more, if you want to.", sourceObjective = "Kill 6 Hecklefang Scavengers.", completion = "Ooooo-oooh aye! The best Hecklefangs are the dead ones.", sourceObjectiveStatus = "unverified-source-field" }
quests[25009] = { id = 25009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At War With The Scarlet Crusade", description = "Though the strength of the Scarlet Crusade wanes, we are still at war.  The report Executor Arren sent me indicates Scarlet Crusaders have been raiding from the ruined tower in southeastern Tirisfal near the Balnir Farmstead under the command of Captain Vachon.\n\nKill 3 of his zealots and 4 of his friars. It should prove to be a devastating blow to the Crusade!", sourceObjective = "Slay 3 Scarlet Zealots and 4 Scarlet Friars.", progress = "I see you have returned but your task is not complete.  Perhaps you are at ease with the mere humans interfering with The Dark Lady's plan?  Or perhaps you can heed the call of duty and slay the Scarlet band that lies only moments away!", completion = "Your actions will slow down the Scarlet Crusade's advancement in Tirisfal quite a bit... hopefully for good.  But other threats loom.", sourceObjectiveStatus = "unverified-source-field" }
quests[25010] = { id = 25010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Deadly New Ally", description = "Shortly before you arrived at the Bulwark, I was approached by the most unusual young undead woman.  She swore enmity against the Scarlet Crusade, so I sent her to work on our enemies to the north.  You say you saw some dead crusaders earlier?  Those were probably her work.\n\nGo check up on her, and see if she can use any assistance in her vendetta against the Crusade... though I wouldn't be surprised if she's already killed them all.", sourceObjective = "Look for your new ally at the Scarlet Encampment in Tirisfal Glades.", completion = "As you look over the ruins of the camp, you hear a whisper behind you.\n\n<\"I could kill you right now if I wanted to.  You'd better watch your step, {race}.\">", sourceObjectiveStatus = "unverified-source-field" }
quests[25011] = { id = 25011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Bigger and Better Things", description = "There isn't much more glory for you here on the Bulwark, {name}.  You've done enough already.  There may, however, be further adventures waiting in Silverpine Forest.\n\nSpeak with my bat man, Timothy Cunningham.  He'll give you a ride to Brill, free of charge.", sourceObjective = "Speak with Timothy Cunningham at the Bulwark in Tirisfal Glades.", completion = "Sure, I'll give you a ride.  If High Executor Derrington asks for it, then technically I have to.", sourceObjectiveStatus = "unverified-source-field" }
quests[25012] = { id = 25012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take to the Skies", description = "If you're headed back to Brill, you'll want to stop by Executor Zygand on your way out.  I hear there's some excitement going on in Silverpine Forest, to the south.  He'll know more than I do.\n\nSpeak with me again when you're ready to head out.", sourceObjective = "Speak with Executor Zygand at Brill in Tirisfal Glades.", completion = "Welcome back, {name}.  I've heard stories from the east.  Who would have thought that a young {race} {class} like you would have been the one to wipe out the last whimpering remnants of the Scarlet Crusade?", sourceObjectiveStatus = "unverified-source-field" }
quests[25013] = { id = 25013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Oomph", description = "<Dithers samples his latest concoction.>\n\nHmm... this isn't quite there.  It needs something to give at a little more zing.  I've got it!  The spiders to the north have a potent venom that'll do the trick.  See if you can extract some for me, {name}?", sourceObjective = "Obtain 4 samples of Vicious Night Web Spider Venom.", progress = "Do you have some venom from a Vicious Night Web Spider yet, {name}?  It's the final component I need in order to test my experiment.", completion = "Ah, this venom will do perfectly, {name}.  Everything else has been added to my concoction and boiled down.  Thank you, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25014] = { id = 25014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandscraper's Treasure", description = "Inside this weathered stone chest at the back of Stonescraper's lair, you find a curious artifact.\n\nShaped like a beetle, its surface is a smooth, brilliant blue, lined with gold. It looks mechanical, but unlike anything you've seen crafted by mortal hands, and very old.\n\nMegs will probably be interested in this.", sourceObjective = "Talk to Megs Dreadshredder.", progress = "Find something?", completion = "You found that in the ogre den? That's...\n\n...nothing to get excited about, I'm sure! I'm sure it's just...a perfectly benign trinket...that I'm going to give you precisely detailed instructions on exactly how to handle.\n\n<Megs drops her voice to a whisper.>\n\nKeep your voice down and don't wave that thing around.", sourceObjectiveStatus = "unverified-source-field" }
quests[25015] = { id = 25015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make 'em Squeal", description = "One of the native species in Kalimdor is the 'quilboar.' Prickly little buggers. Reason enough to hate this continent.\n\nThe raids started shortly after we established our forward camps. Worse, those spiny fiends seem to thrive in this thorny hell of a jungle. I need you to help beat them back so we can re-establish contact with Forward Command.\n\nWhile you're out there, acquire one of those twisted branches their casters seem to be using to manipulate the jungle growth...", sourceObjective = "Kill any combination of 8 Bristleback Bladewardens or Deviate Thornweavers, and collect a Bramblestaff from one of the Thornweavers.", progress = "I should mention, you're probably going to need a machete to hack through this mess.\n\nThis jungle came out of nowhere!", completion = "<Corporal Teegan nods as you deliver your report, then grasps the Bramblestaff with both hands.>\n\nSo, this is what the quilboar are using against us? Do you think they used these to create this jungle?", sourceObjectiveStatus = "unverified-source-field" }
quests[25017] = { id = 25017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Obstacles", description = "For years, this valley has been sealed behind impenetrable gates. Now that the cataclysm has torn them down, the secrets within are ours to discover.\n\nThere are yet some obstacles in the way. From within the gates, the bygone creations of the titans have awoken. They wander aimlessly across the sand, attacking any who approach.\n\nSomeone needs to destroy the golems patrolling the valley; are you up to it?", sourceObjective = "Destroy 6 Sandstone Golems.", completion = "Thank you, {class}. We would be hard pressed to face such enemies without your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[25018] = { id = 25018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andoren Will Know", description = "Listen carefully, {name}. I don't know how those ogres got ahold of it, but that thing's a titan artifact. I'm no expert, but just that fact alone makes it probably older than the sand we're standing on.\n\nI also know that things like this are nothing but trouble. I don't want anything to do with it. Take it south, to the Valley of the Watchers, and give it to a blood elf named Andoren Dawnrise there. And don't ask any questions, babe, please.", sourceObjective = "Deliver the artifact to Andoren Dawnrise at the Valley of the Watchers.", completion = "Of all the...you found this in an ogre den? Unthinkable. I'm amazed they didn't try to smash it to pieces.\n\nWith any luck, {class}, we'll be able to obtain even more fascinating antiquities here...if you're willing to help.", sourceObjectiveStatus = "unverified-source-field" }
quests[25019] = { id = 25019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laying Claim", description = "We are not the only ones who have discovered the value of the Southmoon Ruins. The dwarves of the Explorers' League have swarmed there, taking artifacts and inscriptions for the Alliance.\n\nI don't think I have to explain much further. We will not allow the discoveries here to fall into the hands of the Alliance. Slay as many dwarves as you can, and drive them from the ruins!", sourceObjective = "Kill 10 Dwarven Archeologists.", completion = "Excellent. The less interference from the Alliance, the better.", sourceObjectiveStatus = "unverified-source-field" }
quests[25020] = { id = 25020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragments of Language", description = "At the Southmoon ruins, just east of here, we've made some finds. My colleagues have found stone shards, engraved with ancient writings, newly exposed by the shifting sands.\n\nThe writings are in no known tongue, though they bear resemblance to markings we've seen on other ruins of the titans. Deciphering them could reveal many more secrets.\n\nUnfortunately, my colleagues are also busy defending the tablets from the Alliance. I need you to go to the Southmoon ruins and retrieve the tablets yourself.", sourceObjective = "Collect 5 Ancient Hieroglyphs.", progress = "Do you have the tablets?", completion = "Thank you, {name}. With that dealt with, we can focus our attentions fully on exploring the gateway.", sourceObjectiveStatus = "unverified-source-field" }
quests[25021] = { id = 25021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood to Thrive", description = "To survive in de harsh desert, de Sandfury had to learn all de secrets of blood magic. You drink de blood, you get de power...darkest voodoo, yah? But dere be no room for holdin' back out here.\n\nIf we gonna find de sword, we need blood. Lucky for ya, Mazoga be a traitor, yah? And dere be plenty of Sandfury trolls wanderin' over de hills dere.\n\nGo an' get Mazoga blood...plenty of blood...and we make de ritual to find Jang'thraze.", sourceObjective = "Collect 6 Fistfuls of Blood from Sandfury Trolls.", progress = "Ya ain't been drinkin' it yaself, eh? I need all of it...", completion = "<Mazoga gathers the pile of blood in his hands and raises it to his mouth. It liquifies and pours gorily down his throat.>\n\nDey drink de blood, dey get de power. I drink dere blood...\n\n<Mazoga gives you a wide, blood-smeared grin.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25022] = { id = 25022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Failure to Communicate", description = "I told him he was a fool, but Ambassador Gaines insisted he could negotiate an alliance with the quilboar against the Horde. Even if he succeeded, I for one wouldn't want to fight with those ... pig-men at my side.\n\nWell, Gaines hasn't returned, and General Hawthorne will hold me accountable if I lose one of our best negotiators to these squealing savages.\n\nLocate the Ambassador in this steaming mess of a jungle and rescue him if he's still alive.", sourceObjective = "Rescue Ambassador Gaines from the quilboar in the Overgrowth.", completion = "Good work. Gaines passed through here not long ago on his way to Northwatch and a warm bath.\n\nThe mission wasn't a total loss, though. We've learned a good deal about these quilboar and their leadership structure.\n\nNow we can handle things ... MY way.", sourceObjectiveStatus = "unverified-source-field" }
quests[25024] = { id = 25024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repel the Paratroopers", description = "The Alliance have caught back up with us at just the wrong moment, my friend. We took care of their ships, but they still have planes that are dropping their vaunted 127th Paratroopers onto the coast below.\n\nIt's all that the battlesworn and scouts can do to hold the two ramps against their overwhelming numbers. I'm certain that if you were to aid them, the tide would quickly be turned.", sourceObjective = "Slay 10 Alliance Paratroopers.", completion = "I've not seen a finer display of {class} prowess.", sourceObjectiveStatus = "unverified-source-field" }
quests[25025] = { id = 25025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sang'thraze the Deflector", description = "The blood speaks. I can feel its flow through the sand...drenched in death, a desert of suffering...\n\n<Mazoga's eyes roll back in his head.>\n\nThere! The blood flows to the south, in a valley of bones. Zakkaru! Zakkaru, spawn of Makkari, the dark one who demands sacrifice... his father forced from Zul'Farrak, his ascension interrupted... he will taste blood once more...\n\n<Mazora reels.>\n\nGo, {class}. Zakkaru has Sang'thraze. Ya not be wanting him to keep it, trust me.", sourceObjective = "Defeat Zakkaru and collect the Sealed Sang'Thraze.", progress = "Did the spirits speak true, mon? You got it?", completion = "<Mazoga grins as he takes the sword from you in both hands.>\n\nDidn't like ya much, eh? More in this world craves blood than just trolls, mon.\n\nLet's find the other blade...", sourceObjectiveStatus = "unverified-source-field" }
quests[25026] = { id = 25026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkest Mojo", description = "Jang'thraze eludes me, mon... de blood is not enough. We gonna need somethin' stronger to find it.\n\nWhen you need every troll you got to help out to scrape by, one o' them dyin' on ya is a big problem, mon, an' dat's why de Sandfury learned to raise our dead wit' da voodoo. You fall over, you just get back up again and keep workin'... forever!\n\nDe zombies we make be imbued wit' darkest mojo. You go on to de west an' find a whole mess o' dem, an' get me dat mojo, yah?", sourceObjective = "Collect 6 Darkest Mojo from Sandfury Zombies.", progress = "You got de stuff, mon?", completion = "<Mazoga tilts his head back and inhales the clumps of mysterious material. His eyes flash.>\n\nPowerful stuff, mon... ah, if ya could see what I see now... mebbe you go try it yaself sometime.\n\nThe spirits call...", sourceObjectiveStatus = "unverified-source-field" }
quests[25027] = { id = 25027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Flicked a Fine Vine to Leaf Me", description = "According to Gaines, \"Three-Tooth\" is what the quilboar call their matriarch. She's been twisting the thorns of this crazy jungle to her own ends, and it was her orders that Gaines be \"torn apart and fed to the overgrowth.\" Nice lady.\n\nLet's give her a taste of her own. Take the Bramblestaff you recovered, and use it on Three-Tooth to take her out of the picture. Then kill the crones she's been training, to ensure nobody else can take her place.", sourceObjective = "Use the Bramblestaff on Three-Tooth and kill her 2 Deviate Crones in the Overgrowth.", progress = "I can see why the Horde hates these little nuisances. Have you taken on Three-Tooth yet?", completion = "...Torn limb from limb!? Well, I'd almost feel bad but the burning hatred gets in the way. She got what she deserved.\n\n<Corporal Teegan takes the Bramblestaff and snaps it over his knee.>\n\nProblem solved.", sourceObjectiveStatus = "unverified-source-field" }
quests[25028] = { id = 25028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble From the Ground Up", description = "Teegan's a fool to think the quilboar caused this sudden overgrowth. Look around you. I've been watching these plants bloom and sprout daily - each generation is more mutated than the last. This isn't tribal magic - it's something primal. And dangerous.\n\nThe day before last a great druid passed through our camp. Seek out Naralex, somewhere in the midst of this jungle. He'll know what to do.\n\nAnd bring him some plant samples from around the overgrowth to help his studies.", sourceObjective = "Gather 10 Unusual Flower Buds from Budding Flowers in the overgrowth.", progress = "I am very busy, {class}. This uncontrolled growth threatens to engulf the continent. Do you have any news?", completion = "Ah, samples from different parts of the overgrowth? These will be immensely helpful, yes. Thank you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25029] = { id = 25029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deaths in the Family", description = "The Agamand family was the most prosperous family in Tirisfal Glades.  I used to work their mills...before the plague.\n\nWhen the Scourge first came, the Agamands fortified their home and convinced those in their employ to remain and help them defend.  We were fools, but at least we were loyal fools.\n\nThe Agamands, in their pride, doomed us to undeath.  And now they are minions of the Scourge!\n\nServe the Forsaken by defeating the Agamands who fell to the plague.  Serve me by bringing me their remains.", sourceObjective = "Obtain Gregor's Remains, Nissa's Remains, Thurman's Remains, and Devlin's Remains.", progress = "Do you have the remains of the Agamands?  Are those cursed beasts finally destroyed?", completion = "Revenge has a sweet taste, don't you think?  When you destroyed the Agamands, did you catch any hint of free will within them?  I hope so.  I hope they knew fear before they were smashed into oblivion.\n\nIt is a foolish hope, I know.  But it is a hope I foster nonetheless.", sourceObjectiveStatus = "unverified-source-field" }
quests[25030] = { id = 25030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Haunted Mills", description = "You sense a malign presence coming from within the skull of the beast.  Coleman Farthing may be interested in seeing this.", sourceObjective = "Bring Dargol's Skull to Coleman Farthing at the Agamand Mills.", progress = "Well well... what do we have here?", completion = "Is this Dargol?  He was vicious even in life, with a temper that bit deep and a blade that bit deeper.\n\nUndeath has not done him any favors, though it suits his personality.\n\n<Coleman holds the skull up and peers into the empty eye sockets.>\n\nYes, this was certainly Dargol.  I can sense his malice, even from the remains you've fetched.\n\nYou have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25031] = { id = 25031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head for the Mills", description = "The Agamand Mills, to the west, have been lost to the Scourge.  The Agamand family has been slain, and the entire residence has been claimed by the Scourge.\n\nThis is probably the largest Scourge outpost in Tirisfal, {name}.  If you think you're enough of a {class}, head up there and speak with Coleman Farthing.  He's been doing his best to take the land back, and he'll need help.  Just follow this road, it'll take you right to him.", sourceObjective = "Report to Coleman Farthing at Agamand Mills in Tirisfal Glades.", completion = "Argh!  Get back!  Oh, you're not Scourge, are you?\n\nThank the Banshee Queen that you're here.  I've greatly underestimated how bad it's gotten up here.", sourceObjectiveStatus = "unverified-source-field" }
quests[25032] = { id = 25032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets in the Oasis", description = "Yes, I see the other half now, mon...to the south...\n\nWe be close now, mon. It's in an oasis, buried in de muck beneath de water. Don't delay!", sourceObjective = "Search for Jang'thraze the Protector.", completion = "Mazoga? He's taken the sword? That filthy...\n\n<Trenton glowers for a moment.>\n\nAt least you escaped with your life. The Lasher's bite is a vicious one.", sourceObjectiveStatus = "unverified-source-field" }
quests[25034] = { id = 25034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Front!", description = "I'd love to keep you here behind the lines, but it looks like you've been summoned to the front. Ambassador Gaines - remember him? - has relocated to Forward Command and in his latest missive he's requested you, personally, to assist him.\n\nYou'll find our Forward Command operation south of here, in what's become known as the \"Fields of Blood.\"\n\nBe careful, {name}. The Horde has taken to ambushing some of our officers en route.", sourceObjective = "Locate Ambassador Gaines at Forward Command in Southern Barrens.", completion = "Ah, {name}! I've been talking you up to the General here. Thank you again for saving my life.", sourceObjectiveStatus = "unverified-source-field" }
quests[25035] = { id = 25035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Line", description = "Vol'jin be callin' for an all out attack on da naga that have taken over our northern isle. Many of our men were already engaged with their forces near da bridge, but several of us are breakin' through their lines ta assault their isle itself.\n\nSpeak to Jornun right 'ere to secure a ride to da isle. Once there, seek out Morakki, da Captain of da Watch. He will be tellin' ya how ya can aid in da battle.", sourceObjective = "Speak to Jornun to secure a ride to Spitescale Cove and then seek out Morakki.", completion = "Good to have ya, brotha.\n\nVol'jin makes us all proud in dese moments. It feels good ta be tacklin' threats head on.", sourceObjectiveStatus = "unverified-source-field" }
quests[25036] = { id = 25036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teegan's Troubles", description = "The Admiral will be pleased that Northwatch is almost secured, but if we're to keep a grip on this continent we're going to need to maintain the supply lines to the interior.\n\nJust before the assault I received the strangest of reports from Corporal Teegan, who's in charge of maintaining our contact with Forward Command. Says he's having trouble with the \"jungle?\" There's no jungle in the Barrens!\n\nFollow the upper road out of Northwatch and see if you can render any assistance to our wayward Corporal.", sourceObjective = "Report to Corporal Teegan at Teegan's Expedition in Southern Barrens.", completion = "So, Paxton says there's no jungle in the Barrens? What do you call THIS!?\n\nI've got a pile of supplies to move to the interior and my camp has been overrun by a forest that - I swear - grows by the hour!", sourceObjectiveStatus = "unverified-source-field" }
quests[25037] = { id = 25037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crab Fishin'", description = "Perhaps me agin' body is just growin' too picky after all dese years, but boar meat just ain't goin' down easy no more. More for da new recruits I be thinkin'.\n\nWe just set out some crab traps, but if ya be willin' ta help an impatient old troll, I'd love ta have some fresh crawler meat right now. Dey're all around da island, but da best spot ta be huntin' them is off da eastern coast.", sourceObjective = "Kill Pygmy Surf Crawlers and collect 5 Fresh Crawler Meat.", progress = "Da sea be offerin' few boons as delicious as fresh crawler meat.", completion = "Oi! Tasty, mon. Thank ya for your great kindness, young one. Da spirits shall surely be regardin' ya with great favor.", sourceObjectiveStatus = "unverified-source-field" }
quests[25038] = { id = 25038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gordo's Task", description = "Master want weeds. Us gots big hands and not good at picking. You help us and we not hurt you. Us need gloom weed. Many weeds around here and near road.\n\nWhen you have gloom weed you take to Master Holland in Brill.", sourceObjective = "Collect 3 Gloom Weed and deliver them to Junior Apothecary Holland in Brill.", progress = "Where's that useless abomination? Either you have what I need or you'd best get out there and find it.", completion = "What's this? Gloom weed?! I've no need for Gloom weed! That mindless mass of flesh is out there picking daisies and convincing the Lady knows how many dupes like you into doing the same. No offense.\n\nWe'll deal with the Gloom weed later.  For now, we've got other matters to discuss.", sourceObjectiveStatus = "unverified-source-field" }
quests[25041] = { id = 25041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lion's Pride", description = "Respect the lion, {name}! A ferocious killer. You gotta admire the elegance of the beast... Muscle and claws... Running down its food... So primal...\n\nI'm sorry, my mind wandered. As I was saying, I respect these lions, but they're just murder on our patrols. I mean that literally. The men are afraid to go to the bathroom alone at night. Can you help make our camp a little safer?\n\nBarrens lions like to linger under trees.", sourceObjective = "Kill any combination of 5 Plains Prowlers or Plains Pridemanes.", completion = "Nice work! How was it? Did you enjoy the hunt?\n\nDid you run through tall grasses, the scent of your prey urging you forward, until you leapt at its throat, adrenaline surging as your slavering fangs... Well, something like that.", sourceObjectiveStatus = "unverified-source-field" }
quests[25042] = { id = 25042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marching On Our Stomachs", description = "It's true what they say: An army marches on its stomach. And we've been marching a long way.\n\nI'm thinking if we barbecue up a few of those giant lumbering stormsnouts, we'll have enough meat to feed us for weeks.\n\nStormsnouts are big and slow, so they should be easy to kill. Except... Hey you're not carrying any metal on you are you?", sourceObjective = "Collect 4 Fresh Stormsnout Steaks by killing Stormsnouts in Southern Barrens.", progress = "<Trawley licks his lips, barely able to constrain his drool.>\n\nYou get my steaks yet? Nice and bloody?", completion = "<Sam's eyes bug out of his head as you slam the huge slabs of meat before him.>\n\nOh yeah... oh ... YES! I'll have mine raw. I suppose I can grill some up for the others... How would you like yours?", sourceObjectiveStatus = "unverified-source-field" }
quests[25043] = { id = 25043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fields of Blood", description = "The Horde has taken to calling this region the \"Fields of Blood.\" It's an apt name: these reeds run red with the blood of some of my best men.\n\nI've sent out recon patrols to crush the quilboar and report on the Horde troop movements, but not all of them return. They could use your support out there.\n\nPatrol the fields and seek out the Desolation Grunts that are causing us so much grief. Do not expect them to surrender; their Warchief has instructed them to fight to the death.", sourceObjective = "Kill 10 Desolation Grunts at the Fields of Blood in Southern Barrens.", completion = "Very good. We may never drive the Horde completely from these lands, but with a strong presence we can undermine their will to fight.", sourceObjectiveStatus = "unverified-source-field" }
quests[25044] = { id = 25044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomacy By Another Means", description = "I have not forgotten my brush with death at the hands of the quilboar in that filthy jungle. The General here has ordered some tactical strikes, but he stops short of genocide. I have no such qualms.\n\nTake this horn that I 'borrowed' during my negotiations. Blow the horn within the Bristleback challenge ring west of our position - you can't miss it. I want you to challenge the champion of the Bristleback, Sabersnout, to single combat. His death in front of his followers will leave them in utter chaos.", sourceObjective = "Take the Horn of Challenge to the Bristleback Challenge Ring in Southern Barrens. Blow the horn to challenge Sabersnout and kill him.", progress = "Sabersnout! Is he dead? What's the news?", completion = "A \"Boarpocalypse,\" you say? These animals certainly have a unique idea of \"Single combat!\"\n\nNo matter, you've done well. With the quilboar in chaos I should have no trouble convincing the field commanders to execute any strays they find scurrying about. The General need not know we've stepped up the campaign... it's for the better.", sourceObjectiveStatus = "unverified-source-field" }
quests[25045] = { id = 25045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Line in the Dirt", description = "Strategically, control of a region requires constant observation. See here on this map - I've identified a number of strategic hills, similar to this one, that the Alliance must acquire if we are to keep the enemy under our thumb.\n\nMy scouts have already marked their location on the field. What I need is someone to spearhead their capture, and you're the <man/woman> for the job.\n\nSeek out neutral grey flags on hills to the north, east, and south of the Taurajo Ruins. Capture one and defend it!", sourceObjective = "Capture a neutral hill in the Fields of Blood and defend it against a Horde counter-attack.", completion = "Your report, {class}?\n\n\n\nIncredible, {name}! You're a real asset to the Alliance. I'll see to it that my men follow your example!", sourceObjectiveStatus = "unverified-source-field" }
quests[25046] = { id = 25046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Daughter's Embrace", description = "The whisper continues:\n\n<\"My name is Lilian Voss.  Before I died, I was a member of the Scarlet Crusade.  My father, High Priest Voss, raised me to be a weapon against the plagued.  I studied stealth, sorcery, martial arts, anything to make myself stronger.  I gave up my childhood for him.\">\n\n<\"Then, as fate would have it, I died and returned as... this.  My father instantly forgot me and, when I returned, ordered me executed.\">\n\n<\"Come.  We will speak with him now, in his tower to the northwest.\">", sourceObjective = "Bring Lilian Voss to her father in the tower at Crusader's Run.", completion = "From birth to grave to undeath, we all have our own path to follow.  Some are easier than others.  It sounds like this Voss girl has had a rough path so far.\n\nHopefully she ultimately chooses to join us and follow the Dark Lady.  With power like hers, we could do incredible things.\n\nBy the way, {name}... excellent work out there.  If you're ever ready and willing, I may have some more work for you in the Plaguelands.", sourceObjectiveStatus = "unverified-source-field" }
quests[25047] = { id = 25047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Panther Figurine", description = "This badly broken figurine was discarded by its last owner.  However, with the right materials and your skill in jewelcrafting, it could be completely restored.", sourceObjective = "Repair the broken figurine using your skill and materials.", sourceObjectiveStatus = "unverified-source-field" }
quests[25048] = { id = 25048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seaside Salvage", description = "If we want to convince Mister Noggenfogger to let us move more gnomes here, we've got to show him just how nice we are! I know just the thing.\n\nGadgetzan's under blockade by pirates, but plenty of the goods that get blown off the ships survive intact... they just wash away. Most of them wash up in the shallows just south of town.\n\nIf you could go collect those supplies for them, it'd help us make friends! And it'll keep that mean goblin girl over there from taking them and selling them.", sourceObjective = "Collect 7 Steamwheedle Supplies.", progress = "Do you have a whole buncha boxes? Let's see!", completion = "Most of this looks just fine! How lucky!\n\nThe Steamwheedle goblins will be so happy to see their cargo back safe and sound. And here's a reward for your good deeds, of course!\n\nWe've got lots of other stuff to do though! Busy busy!", sourceObjectiveStatus = "unverified-source-field" }
quests[25049] = { id = 25049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Puddle Stomping", description = "There's a big problem here! It's great that the ocean came in so far, because now ships can get to Gadgetzan. But now there's a bunch of nasty old sea giants encroaching on the town! I'm sure Mister Noggenfogger would appreciate us taking care of them for him.\n\nDon't worry, I won't ask you to do it just out of the goodness of your heart! Take care of them and I'll give you a reward!", sourceObjective = "Kill 8 Tidal Striders.", completion = "Oh, it's going to be so much nicer around here now that they're gone!\n\nAt least until more show up. But thank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[25050] = { id = 25050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocket Rescue", description = "When the water came in, Steamwheedle Port to the east was flooded, and a lot of poor goblins are still stuck there! Now those mean pirates are shooting at any boat that leaves the docks here.\n\nBut they won't expect us to fly! There's a hot air balloon by the docks. We can use that, fly over to rescue the goblins, and take care of the pirates, too. Mr. Noggenfogger will be so pleased!\n\nGo to the docks and hop in the balloon and I'll be right behind you, okay? I've got to get some rockets...", sourceObjective = "Deliver Liferockets to 5 Steamwheedle Survivors and use bombs to kill 40 Southsea Blockaders.", progress = "Let's not wait around, silly! We weren't done yet! We've gotta get out there!", completion = "That was great! It looks like most of the goblins we helped made it back here and didn't blow up. We really showed that goblin girl!\n\nHere's a special reward for you, mister.", sourceObjectiveStatus = "unverified-source-field" }
quests[25051] = { id = 25051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmist Extermination", description = "The spiders that occupy Darkmist Cavern to the northwest are another vicious threat to us here. They are nothing the ogres cannot handle, but splitting our attention to them when Theramore's forces lurk nearby is a deadly mistake.\n\nI need someone to destroy the eggs inside Darkmist Cavern, to cut off this infestation. You will find the eggs in the deepest part of the webbed mines... along with their guardians.", sourceObjective = "Destroy 8 Darkmist Eggs in Darkmist Cavern.", completion = "This is a great relief, {class}. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25052] = { id = 25052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead Man's Chest", description = "Well gosh, as you can plainly see there's this really big battle with these pirates here going on. We're doing our best to make sure they never bother Gadgetzan or our new gnomish homes there ever again!\n\nBy killing them.\n\nSo how about helping us? We really wanna make sure we kill more than green-nose over there and her awful thugs. I'd really appreciate it!", sourceObjective = "Kill 15 Southsea Pirates.", completion = "Good job! We're really cleaning up around here!", sourceObjectiveStatus = "unverified-source-field" }
quests[25053] = { id = 25053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To The Ground!", description = "You know, this place would probably make a great home for us gnomes if it wasn't so old and dirty and full of pirates! We're taking care of the pirates problem, but the awful and dirty problem needs fixing.\n\nI mean, no self-respecting gnome would ever live in such an ugly hovel like these buildings! So here, take this bottle of flaming rum and go burn those ugly shacks down for us!", sourceObjective = "Use the Burning Rum to set fire to the Northwest Shack, the Northeast Shack, and the Southwest Shack.", completion = "Isn't that just so pretty to watch?", sourceObjectiveStatus = "unverified-source-field" }
quests[25054] = { id = 25054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lootin' Plunder", description = "It's just really so wasteful that all these pirates have golden treasures lying around. Some of this stuff could be used for practical things! Like melting into wire, or intrinsic shielding matrices, or selling to other stupid races that buy gold just to keep it around.\n\nAnd speaking of other stupid races, I bet those greedy goblins are going to be taking all of it. We can't let that happen! Go collect that treasure for Gnomeregan!", sourceObjective = "Collect 10 pieces of Pirate Loot.", progress = "I hope you don't think you're hiding any for yourself, silly! These goggles can see right through your bags.\n\nAnd your armor.", completion = "Fantastic! Gosh, this will make enough wire for an entire army.\n\nLucky us!", sourceObjectiveStatus = "unverified-source-field" }
quests[25055] = { id = 25055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Research" }
quests[25056] = { id = 25056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grisly Grizzlies", description = "Have you seen the plagued bruins that wander to the west of here?  Those hides... so hideous, so diseased, so... perfect!\n\nFetch me 5 of them.  I've got an idea for an anti-Scourge poison that's guaranteed to succeed!", sourceObjective = "Obtain 5 Plagued Bruin Hides.", progress = "Let's see... do you have enough hides?", completion = "Dithers, you've done it again!  These are perfect.", sourceObjectiveStatus = "unverified-source-field" }
quests[25057] = { id = 25057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clap 'Em In Irons", description = "Our policy of conscripting non-violent criminals from the Stormwind Stockades has come back to haunt us, {name}. Some of my less-scrupulous soldiers broke ranks after our victory in Taurajo and are looting the remains of the city.\n\nThis is a breakdown in discipline. Worse, the desecration of their homes only spurs the enemy to fight harder when our ultimate goal should be peace.\n\nTake these manacles and bring the Taurajo looters to justice. Speak to them first, but you may need force to subdue them.", sourceObjective = "Speak to the Taurajo Looters in the Taurajo Ruins and place them under arrest. Use the Northwatch Manacles to subdue 5 wounded looters.", progress = "Is the Taurajo situation under control?", completion = "Well done, {name}. Several of the looters have already crawled back, requesting clemency. I'll let them stew for a bit in the Northwatch brig.\n\nThank you for helping maintain discipline in the ranks. It is important for our army to be perceived as soldiers, not common bandits.", sourceObjectiveStatus = "unverified-source-field" }
quests[25058] = { id = 25058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mine Disposal, the Goblin Way", description = "The paratroopers have mined the beach!\n\nThe Warchief asked me if there's anything we can do about that. I told him, 'You bet we can!'. I was thinking maybe you could take this satchel of grenades and detonate the land mines from a safe distance?\n\nIt's how we do things, right?!", sourceObjective = "Detonate 10 Land Mines.", progress = "Boss, do you think you could go back down there and detonate a few more?\n\nThanks!", completion = "Score one for the goblins! Stupid dwarves and gnomes.", sourceObjectiveStatus = "unverified-source-field" }
quests[25059] = { id = 25059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Taurajo Briefs", description = "The General is too preoccupied with the looters in Taurajo. Too soft! We ought to be focused on our next move against the Horde.\n\nThere's valuable intelligence that might be compromised if we allow the ruins of Taurajo to continue to burn. While you're running the General's errand, dig around for any maps or notes you can find. I can speak a little of the orcish tongue - I'll be able to make sense of what you find.", sourceObjective = "Search the Ruins of Taurajo for 3 pieces of Taurajo Intelligence.", progress = "Have you searched the ruins yet?", completion = "What have you dug up for me? Hmm. Interesting. This notice from Orgrimmar indicates a change in Horde leadership is underway - I guess heads are going to roll after what we did to Taurajo.\n\nWhat's this? A death warrant for the General here! This is good to know... Very good to know...", sourceObjectiveStatus = "unverified-source-field" }
quests[25060] = { id = 25060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Define \"Crazy\"", description = "We received reports that a goblin shipwreck occured on this beach some time ago, with the survivors left to fend for themselves. We expected there to be a modicum of survivors, perhaps some even suitable for interrogation.\n\nWhat we found was a crew of Bilgewater goblins who have all become insane, delusional, and maniacally violent...to further degrees than is normally observed, rather.\n\nIn short, they are useless and dangerous. Gnomeregan will be best served by cutting down as many as we can.", sourceObjective = "Kill 10 Crazed Survivors.", completion = "Your reports of their behavior are truly disturbing...but also slightly amusing.\n\nIf only that Dreadshredder wench had escaped on these vessels instead...", sourceObjectiveStatus = "unverified-source-field" }
quests[25061] = { id = 25061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Land's End", description = "Psst! Hey! Come closer, you fool, you expect me to read your mind or--oh. Come closer anyway!\n\nYou've done a wonderful job advancing the agenda of Gnomeregan here, friend! And an amazing job of pretending you were only in it for the coin, simply splendid. But now Kelsey Steelspark could use more of your direct help.\n\nShe's moved on yet again...she asked me to tell you to meet her far south, at Land's End Beach. I wouldn't keep her waiting, either!", sourceObjective = "Talk to Kelsey Steelspark at Steelspark Station.", completion = "I'm amazed that Soothfancy was capable of following a simple set of instructions. And ones that required him to keep his foolish mouth silenced as well.\n\nIn addition, it is honestly good to see you again, {name}. Now that I've dropped the charade, you'll get to see how gnomes get things done around here.", sourceObjectiveStatus = "unverified-source-field" }
quests[25062] = { id = 25062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What We Came For", description = "Gnomeregan previously learned that the Bilgewater goblins of the Horde survived a crash on an uncharted island near Kalimdor before arriving in Durotar. We initially came here to investigate what techniques and technology could possibly allow a hopeless pack of imbeciles to survive such harsh conditions.\n\nWhile the goblins are at a loss, we still need to find out exactly what happened here. Search the beach for wreckage and belongings and bring anything that appears significant back to me.", sourceObjective = "Search Bilgewater Footlockers for evidence.", progress = "What have you found?", completion = "<Kelsey takes the journal and gingerly flips through it.>\n\nI'm trying not to laugh. This is classic. They have no idea they're even on Kalimdor!\n\nThese later pages though...something more significant may be occurring here.", sourceObjectiveStatus = "unverified-source-field" }
quests[25063] = { id = 25063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrapination", description = "We need to obtain the object described in this journal, for certain. Extracting it from a chest would be a feasible matter, but the object itself sounds compromised, and unstable. Attempting to forcefully open the chest could be disastrous.\n\nFortunately, we know where the key is...statistically speaking, at least. There's plenty of sea turtles at the east end of this beach. One of them may hold the key.", sourceObjective = "Obtain a Turtle-Digested Key from a Surf Glider.", progress = "Hopefully your spree of turtle destruction left it intact.", completion = "Well, gosh, this day just keeps getting better and better! I may actually smile.\n\nWhen you're not looking. You've seen enough of that already.", sourceObjectiveStatus = "unverified-source-field" }
quests[25064] = { id = 25064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moraya", description = "Moraya has been lookin' for some help with tha raptors. Ya should talk to her on the other side of Darkspear Hold when ya get a chance.", sourceObjective = "Speak with Moraya.", completion = "Hey there, hon. Vol'jin sent you? So sweet of him to be thinkin' of me.\n\nI surely could use da help, but ya have a bit more walkin' ahead of ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[25065] = { id = 25065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Too, Brute?", description = "It's time to conclude this matter efficiently. From what we've determined, this mysterious object is in the possession of the \"smart\" brute described in the journal. We don't know exactly what's happened to this creature, obviously, so you should take caution.\n\nThis... \"Meatface\" is hiding in the hills, near where these goblins bury their dead. Look for the graveyard and he should be just past it.", sourceObjective = "Obtain Meatface's Chest.", progress = "Do be careful with the contents of the chest.", completion = "Well done, {name}. The contents of this chest are sure to advance Gnomeregan's knowledge base significantly. I believe you've earned a reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[25066] = { id = 25066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pride of Kezan", description = "This is ridiculous! Those gnomes just don't know when to stop!\n\nGoblin pride is on the line here! {name}, you gotta jump into the Pride of Kezan and show them what's what!\n\nLet me know when you're ready!", sourceObjective = "Shoot down 10 Gnomeregan Stealth Fighters.", progress = "What are you doing back here? Get up there and shoot them down!", completion = "YES!", sourceObjectiveStatus = "unverified-source-field" }
quests[25067] = { id = 25067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderdrome: The Ginormus!", description = "The rules are simple: Two men enter, one--wait. Sometimes there's women.\n\nTwo people enter, one--Wait, no, sometimes it's more than two...and that means more than two come out--\n\nAlright, only rule is stay in the drome! There are no other rules!\n\nYou're up against the biggest, baddest member of the Wastewander Bandits first. This'll either be a warmup or a bloodbath...it's up to you which!", sourceObjective = "Defeat Lord Ginormus.", progress = "Stop wasting my time. Enter and fight!", completion = "An impressive start. Be prepared for more.", sourceObjectiveStatus = "unverified-source-field" }
quests[25068] = { id = 25068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crumbling Past", description = "The creatures wandering these ruins are Earthen, the ancient ancestors of dwarves, made by the Titans to shape the world itself.\n\nThe original Earthen broke down and went awry thousands of years ago, and these freshly uncovered ones seem no different. We may as well make use of these confused and unstable constructs.\n\nEnter the ruins and destroy the Earthen, and collect the jewels embedded in them; their magical energies will be both valuable and worthy of study.", sourceObjective = "Collect 5 Earthen Jewels.", progress = "Handle those carefully, {name}; they are as ancient as the world itself.", completion = "Marvelous. To think the shapers of our world crafted these...", sourceObjectiveStatus = "unverified-source-field" }
quests[25069] = { id = 25069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secrets of Uldum", description = "We are ready to enter the antechamber itself, {name}. This is a momentous occasion.\n\nFrom the writings you've brought us, I believe these ruins were in fact once the grand entrance to Uldum itself. The quakes that ripped its doors open have probably collapsed the tunnels, but we may yet find amazing things hidden within.\n\nSearch the ruins for anything intact that may be studied.  The thrill of discovery awaits!", sourceObjective = "Search the Antechamber of Uldum for an intact artifact.", completion = "This chest lies undisturbed, sealed for thousands of years.", sourceObjectiveStatus = "unverified-source-field" }
quests[25070] = { id = 25070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Lies Within", description = "As you lay your hand upon the chest, a faint rumbling can be heard. The sound of grinding movement echoes behind you as the chest begins to shut itself.\n\nSomething is approaching!", sourceObjective = "Defeat the Antechamber Guardian.", completion = "The chest now grinds open again, the rest of the antechamber fallen silent.", sourceObjectiveStatus = "unverified-source-field" }
quests[25072] = { id = 25072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Few Good Goblins", description = "We haven't just been camped here singin' songs with gnomes and playing with dangerous machinery, you know. My men have been trying to clear this hive out for a week now! Problem is, we've taken so many losses by now that the bugs have the advantage.\n\nLucky for us, the bugs either don't like to eat goblins, or they like us so much they save us as treats, because nearly all my men are still cocooned up out there. I need you to go save 'em.", sourceObjective = "Save 8 Captured Goblin Bughunters from Hazzali Cocoons.", completion = "Thanks for the help, this was really killin' things here. Once you start losing men, you start losing manpower. And morale. And weapons. And the magazines you loaned to that one guy.\n\nYou know how it is.", sourceObjectiveStatus = "unverified-source-field" }
quests[25073] = { id = 25073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sen'jin Village", description = "You've be doin' quite well for one so young. I've no doubts you'll be makin' quite da name for yarself.\n\nGo now, northwest, across da shallows ta Sen'jin Village. Dere you'll be meetin' Master Gadrin. He'll likely have a task or two for ya before ya truly make ya way out into the Durotar wilds.\n\nPlease remember, {name}, we may disagree wit' the young Hellscream at times, but his intentions are noble, and it be very important that we remain united as one Horde. Make da Darkspear proud.", sourceObjective = "Report to Master Gadrin in Sen'jin Village.", completion = "Welcome, young {race}.\n\nYa come highly recommended, mon. It's nice ta finally be meetin' ya in person.", sourceObjectiveStatus = "unverified-source-field" }
quests[25074] = { id = 25074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet Me at Triumph", description = "Thanks in part to your efforts, we've stabilized the situation here. We need to turn our attention south, to Fort Triumph.\n\nFort Triumph is the keystone of our operation in the Barrens - the vital land-link between Northwatch and Theramore.\n\nI'll pack up and head out separately. Report to Commander Roberts at the fortress and I will see you there soon. Together, we will secure the frontier!", sourceObjective = "Report to Commander Roberts at Fort Triumph in Southern Barrens.", completion = "Have you heard? The General never made it!\n\nKilled in the field, like some kind of dog!", sourceObjectiveStatus = "unverified-source-field" }
quests[25075] = { id = 25075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pick-a-Part", description = "These bulky dwarven siege engines aren't cut out for the close-quarters fighting of the Battlescar.\n\nI've got some new designs I'd like to try out, but first I'm going to need some spare parts. There's plenty of wreckage sitting in the Battlescar. All I need is an enterprising {class} to haul it back for me.\n\nThat's you, {name}. I'm talking about you.", sourceObjective = "Collect 8 Siege Engine Scrap pieces from the Battlescar in Southern Barrens.", progress = "What have you got for me?", completion = "Oohh look! A mostly complete exhaust manifold, a reciprocating junction box, a working counterweight slip differential ... you sure know your junk, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25079] = { id = 25079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Powder Play", description = "Our shipments of saltpeter from Dustwallow have been held up, which means we can't manufacture our own gunpowder here.\n\nBut I can retrofit our armaments to use goblin Blast-O powder. It's unstable, dangerous, toxic to the skin, and harmful if swallowed... but I think I can make it work!\n\nGet me a keg of the stuff by attacking one of those goblin sapper specialists who've been storming our walls.", sourceObjective = "Defeat a Sapper Specialist near the Battlescar and acquire a Keg of Blast-O Powder.", progress = "Do you have a keg of Blast-O powder yet?\n\nWhen you get one ... don't shake it.", completion = "Great! Set the keg down right here. I'll measure out some charges once I've donned my full-body protective gear.", sourceObjectiveStatus = "unverified-source-field" }
quests[25080] = { id = 25080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Batteries Not Yet Included", description = "Okay! Using the spare parts you've found for me, I've got a framework roughed out for my versatile new assault vehicle. All I need now is a compact power supply.\n\nI've noticed that the indigenous wildlife here packs quite the punch, electrostatically speaking. Can you hunt down Thunderheads near the base here and get me an intact electrogizard? It might take a few kills to find a usable gland.", sourceObjective = "Acquire a Humming Electrogizard from a Thunderhead in Southern Barrens.", progress = "It must be an enormous evolutionary advantage to be able to shoot lightning. From your face.", completion = "<The gizard shocks Mizzy as you hand it over, blasting her to the ground.>\n\nOh, OH! That's nasty! I love it!", sourceObjectiveStatus = "unverified-source-field" }
quests[25081] = { id = 25081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claim the Battlescar", description = "The Horde has fought us to a standstill from their stronghold west of here. The fighting continues, even as the land breaks open under our feet.\n\nSomeone's got to break the stalemate! I need you to venture into the Battlescar and help my men crush the Horde opposition there.\n\nIn the center of the scar you will find a flag marker designating who controls the area. Scout out the flag. It'll be worth your while to claim the scar for the Alliance if someone hasn't already done so.", sourceObjective = "Go to the Battlescar. Scout out the flag marker and kill 10 Desolation Raiders.\n\nCapturing the flag will give all Alliance players in the scar a combat advantage.", completion = "Incredible work, {name}! My men report a breakthrough. Their stronghold won't survive much longer...", sourceObjectiveStatus = "unverified-source-field" }
quests[25082] = { id = 25082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Working the Bugs Out", description = "Why high command decided that a silithid mound was the ideal place to build a fortress, I'll never know. Them lil' buggers are tunneling under our fortifications and setting back our timetables. We need to scorch 'em out!\n\nTake this here bucket of burning pitch and dump it on the silithid mounds right outside the main gate. They look like big piles of sand. Kill anything that comes out, but be careful, {name} - them nasties are likely to swarm you when you light those mounds up.", sourceObjective = "Use the Bucket of Burning Pitch on the silithid mounds outside of Fort Triumph to flush out and kill 10 Silithid Swarmers.", progress = "How goes the fight, {name}?", completion = "That oughta take care of our bug problem for a while - they'll be hard-pressed to tunnel their way outta that!", sourceObjectiveStatus = "unverified-source-field" }
quests[25084] = { id = 25084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Growing Threat", description = "A moment there, {class}.\n\nWe've got more problems here than just the end of the world as we know it. Our vigil here's threatened by the quilboar. We've been content to leave them be when they stay in the Kraul, sure, but every day they press further and further out towards our camp.\n\nMahka, bless her green heart, wouldn't ever forgive me if I went out bashing heads in myself, but if you could help drive back those that're wandering near the camp, I'd appreciate it.", sourceObjective = "Kill 13 Razormane Quilboar.", completion = "You've my thanks, if not that of the entire Earthen Ring.\n\nMaybe someday we'll find a way to talk it out with these pigs, but we can't heal the land if we're dead in our sleep.", sourceObjectiveStatus = "unverified-source-field" }
quests[25085] = { id = 25085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mangletooth", description = "Una here used to spend time in Camp Taurajo. She's told me about a quilboar that used to be captured there, named Mangletooth. Quite the clever one, for a quilboar.\n\nI've been tryin' to think what got these quilboar riled up so much recently, and it might be that Mangletooth escaped Taurajo alive. If he has, he's certainly calling the shots.\n\nThere's a large hut up in the hills to the northwest. If you find Mangletooth there, cut 'im down.", sourceObjective = "Kill Mangletooth.", completion = "That's a relief. Maybe the rest of 'em will keep to their own devices now. The less fighting around here, the better.", sourceObjectiveStatus = "unverified-source-field" }
quests[25086] = { id = 25086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firestone Point", description = "Can you do me a huge favor, {name}? My sister-in-law's uncle is in the Earthen Ring, and he's here in the Barrens studying the impact of the Cataclysm, down at Firestone Point. He says their camp is surrounded by quilboar and I worry that they might get overrun.\n\nCan you check in on Dorn Redearth for me? I'd hate for anything to happen to him, what with the close family bond and all.", sourceObjective = "Seek out Dorn Redearth at Firestone Point in Southern Barrens.", completion = "What? Little Logan thinks I might need protection?\n\nIt's me doing the protectin'!\n\nThe quilboar here are poised to rampage. They've choked off the entire south, and we're the only thing standing in their way.", sourceObjectiveStatus = "unverified-source-field" }
quests[25087] = { id = 25087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Twinbraid", description = "The Alliance owes a debt to the dwarves of Bael Modan, who built some of our earliest fortifications in the Barrens.\n\nTheir commander, General Twinbraid, is a real stalwart. One of our best. He's on patrol south of here, keeping the Horde on their toes.\n\nI definitely want to keep him appraised of the situation here so we can coordinate our next move. Can you deliver this frontline report to him in the field?", sourceObjective = "Deliver the Frontline Report to General Twinbraid, who is on patrol in Southern Barrens.", progress = "Hrm, news from the fortress? Well. Spit it out!", completion = "<The General reads over the report, nodding in approval as he reads about the Battlescar.>\n\nQuite a name you're earning for yourself here in the Barrens, {name}. But Roberts isn't going far enough. What we need is a decisive victory...", sourceObjectiveStatus = "unverified-source-field" }
quests[25089] = { id = 25089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beyond the Graves", description = "Darnell tells me that the two of you have already met.  That's good, because I'm sending you both into Deathknell.  Your work is done here.\n\nSpeak with Deathguard Saltain in Deathknell, to the north.  He will tell you more of what you must know.", sourceObjective = "Speak with Deathguard Saltain at Deathknell in Tirisfal Glades.", completion = "Those val'kyr have been really busy resurrecting you newbies lately.  I've already seen a couple dozen new bodies run down that hill since this morning.\n\nYou, however, are the most promising {class} I've seen today.", sourceObjectiveStatus = "unverified-source-field" }
quests[25090] = { id = 25090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Putrid Task", description = "Scourge have trickled into Tirisfal Glades and have infested this area.\n\nI need someone to beat back the rotting dead and ravaged corpses that have taken this small farm.  Scatter their bones and bring back their putrid claws.  The Deathguards will reward you.", sourceObjective = "Bring 7 Putrid Claws to Deathguard Dillinger in Cold Hearth Manor.", progress = "Have you completed the task with which I have charged you?  Do you have those putrid claws?", completion = "Well done.  I enjoyed watching you smash those {race} into rotting pulp!", sourceObjectiveStatus = "unverified-source-field" }
quests[25091] = { id = 25091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandsorrow Watch", description = "If you're looking for more work, I've got a line for you.\n\n I know an elf by the name of Trenton Lighthammer who's been obsessed with the sand trolls near here for years. He's dead-set on finding some kind of mythical sword made by them, and just a while ago he finally got a crew together to go to Sandsorrow Watch and look for it.\n\nLast I heard, they kicked the trolls out of one of their camps and set up shop there. Look for it to the west, near Zul'Farrak.", sourceObjective = "Speak with Trenton Lighthammer at Sandsorrow Watch.", completion = "Marin sent you? I'm appreciative of his help.\n\nI'm here to seek out Sul'thraze. If you wish to help, speak with Mazoga...he's been cooperative so far.", sourceObjectiveStatus = "unverified-source-field" }
quests[25092] = { id = 25092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Research" }
quests[25093] = { id = 25093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heads of the SI:7", description = "These orcs were murdered in cold-blood by the Alliance down on the coast. We did nothing to provoke them.\n\nTheir deaths should not be in vain, {name}. Will you bring them justice?\n\n<Aggra appears as if she can barely contain her rage.>\n\nThere are three SI:7 leaders down there along the beach. Bring me each of their heads.", sourceObjective = "Collect the heads of Commander Arrington, Darkblade Cyn, and Alexi Silenthowl.", progress = "Has justice been served?", completion = "Thank you, {name}. The spirits of the fallen can now be put to rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[25094] = { id = 25094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderdrome: Zumonga!", description = "Splendidly done! But you'll be fighting more than mere humans!\n\nYour next opponent's a mean one...watch out for his right hook. And his left. I'd be wary of his fists in general.", sourceObjective = "Defeat Zumonga.", progress = "Stop wasting my time. Enter and fight!", completion = "Not bad. You've got a ways to go, however.", sourceObjectiveStatus = "unverified-source-field" }
quests[25095] = { id = 25095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderdrome: Sarinexx!", description = "I hope you're ready for the next one, {name}. One mistake could mean instant, painful death! But that's what the people pay to see, isn't it?\n\nI hope you're not afraid of bugs...", sourceObjective = "Defeat Sarinexx.", progress = "Stop wasting my time. Enter and fight!", completion = "Rather impressive. Few can bear to see a silithid reaver face to face, let alone defeat it.", sourceObjectiveStatus = "unverified-source-field" }
quests[25098] = { id = 25098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warchief Wants You", description = "True to his word, Thrall is going to get us going in the right direction to rescue our people. He asked to speak with you.\n\nGood luck, {name}. We're all depending on you.", sourceObjective = "Speak with Thrall at the Warchief's Lookout on the Lost Isles.", completion = "Once again you have helped us to overcome our mutual enemy, the Alliance.\n\nNow it is time for us to help you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25099] = { id = 25099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Borrow Bastia", description = "Head back down to the coast and tell Kilag that I'd like for you to borrow Bastia. The panther knows the way to where your friends are being held captive.\n\nGo now. I will see you again before we make our move against the Trade Prince.", sourceObjective = "Speak with Kilag Gorefang at the Tranquil Coast on the Lost Isles.", completion = "Of course you can borrow Bastia. That is, if she'll take you.\n\n<Kilag winks.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25100] = { id = 25100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let's Ride", description = "Bastia will make sure that you get to where you need to go, goblin.", sourceObjective = "Speak with Slinky Sharpshiv at Sky Falls on the Lost Isles.", completion = "{name}?! Nice kitty.\n\nLook we don't have much time here. You might have noticed that the volcano is blowing?!", sourceObjectiveStatus = "unverified-source-field" }
quests[25102] = { id = 25102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Bull", description = "Twinbraid's patrols always throw us right into the thick of danger. If it's not Horde ambushes, it's a quilboar hit-and-run.\n\nThe problem is them lousy landquaker kodos. Big walkin' walls of fur, shakin' the ground... We can't see or hear an ambush creepin' up on our backside.\n\nGo scare 'em off from our patrol, here. Killing a few should drive the herd south and out of what's left of me hair.", sourceObjective = "Kill 4 Landquaker Kodos and 1 Landquaker Bull in Southern Barrens.", completion = "I thought you might be responsible for them clouds of dust I saw to the east. Nice work! Them bulls ain't sissies.", sourceObjectiveStatus = "unverified-source-field" }
quests[25103] = { id = 25103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bootlegger Outpost", description = "We've done a bang up job here. I'm gonna make sure these mooks finish properly and then head back to Gadgetzan for a bit.\n\nIf you want to keep making a good impression on our Steamwheedle friends, or just make more money, you should head southwest of here. Bootlegger Outpost is set up on the edge of the gaping chasm.\n\nTalk to Zeke Bootscuff. I'd bet good money he'll need help.", sourceObjective = "Talk to Zeke Bootscuff at Bootlegger Outpost.", completion = "You're with Megs, huh? Word is she's been pretty hell-bent on making nice with Noggenfogger.\n\nNot like I care. Are you ready to kill some bugs?", sourceObjectiveStatus = "unverified-source-field" }
quests[25104] = { id = 25104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Digsite Status", description = "The patrol's been quiet today. And that's got me worried, {name}.\n\nEver since the Alliance sacked Taurajo, none of our positions are secure. You look like you can handle yourself - can you scout around for me?\n\nCheck in with my son Marley outside the Bael Modan excavation, southeast of here. The site's exposed and susceptible to raids, and my son's too proud to signal for help if he needs it.", sourceObjective = "Locate Marley Twinbraid outside the Bael Modan Excavation in Southern Barrens.", completion = "Father sent you? He worries too much. There's nothing here I can't handle...\n\nBut I'd still appreciate the help.", sourceObjectiveStatus = "unverified-source-field" }
quests[25105] = { id = 25105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nibbler! No!", description = "Lila's pet Nibbler got into my workshop again!\n\nI was making a bracelet, to be delivered today.  The work was almost done, except for the gems.  I spent all night cutting them, but when I stepped out for a bit of breakfast, the little beast came into my workshop and swallowed every gem in sight!  The thing can digest ANYTHING, and trust me, you'd break your back trying to pick up its leavings.\n\nI need to get replacement gems fast; the courier is coming in tonight.  Help!", sourceObjective = "Cut three Solid Zephyrites and give them to Isabel Jones in Stormwind City.", progress = "Have you brought the solid zephyrites I need?", completion = "You've really saved my skin, {name}.  Thanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[25106] = { id = 25106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hands Off Me Dig!", description = "Look at the chaos down there, {name}! I've instructed the foremen to save what artifacts they can. Who knows what treasures these tauren animals are like to make off with.\n\nCan you help get a handle on things? Kill the raiders and save what artifacts you can.\n\nWhile you're at it, look for my missing tools. A few quick repairs and I can get this flying machine up and running again.", sourceObjective = "Kill 8 Excavation Raiders, rescue 5 Bael'modan Artifacts, and acquire Twinbraid's Tools in the Bael'modan Digsite.", progress = "How's the situation down there?\n\nWhen the raid started I popped a bullet into their ringleader, Stonespire, but they just kept right on coming.", completion = "My father would be proud of you, {name}.\n\nNow, to get this flying machine up and about again...", sourceObjectiveStatus = "unverified-source-field" }
quests[25107] = { id = 25107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Tablet", description = "At the bottom of the chest, you find a large tablet. Made of a material resembling stone, but completely smooth and flawless, it is covered in strange writing.\n\nWhile some resembles the writing on the walls, other scripts appear completely different. Andoren would probably like to see this.", sourceObjective = "Take the Grand Tablet to Andoren Dawnrise.", progress = "You're back! What have you found?", completion = "This is truly incredible. The hieroglyphs are undoubtedly titan, but the markings below it...\n\nSome of these characters resemble ancient Kaldorei writings. And you say the antechamber was covered in hieroglyphs?\n\nYou've made a find more monumental than any riches, {name}. Please, take whatever reward you prefer.", sourceObjectiveStatus = "unverified-source-field" }
quests[25108] = { id = 25108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feegly the Exiled", description = "Saddest story I ever heard told, {name}. Feegly was one of our fastest diggers, until he got a hold of that - thing. \"The Tear of the Moons\" we called it. It changed him. Remade him. I wish it had stayed buried.\n\nFeegly was banished from Bael Modan but I've heard reports he's come sniffing around the dig site again. He's suffered enough, the wretched thing. If you find him down there, put ol' Feegly out of his misery.", sourceObjective = "Kill Feegly the Exiled in the Bael Modan Digsite.", completion = "<Marley nods grimly.>\n\nAye, it's for the best I suppose.", sourceObjectiveStatus = "unverified-source-field" }
quests[25109] = { id = 25109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gallywix Labor Mine", description = "We barely escaped with our hides intact!\n\nThe Trade Prince has a whole bunch of us enslaved and performing manual labor inside the cavern.\n\nGreely helped the seven of us to get out, but she was recaptured in the process.\n\n{name}, you're the only one crazy enough to walk into an exploding volcano! The assistant will be able to help you free the others.\n\nHurry! This place is about to blow for good!", sourceObjective = "Speak with Assistant Greely inside the Gallywix Labor Mine on the Lost Isles.", completion = "<The assistant looks confused.>\n\nHuh... what? Who?", sourceObjectiveStatus = "unverified-source-field" }
quests[25110] = { id = 25110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaja'Cola Gives You IDEAS! (TM)", description = "Assistant Greely is clearly bewildered and intimidated. How will she help you to find a way to rescue everyone in this condition?\n\nMaybe if she were to drink one of those Kaja'Cola Zero-One drinks you saw, she'd be able to have a bright idea?", sourceObjective = "Collect 1 Kaja'Cola Zero-One.", progress = "Huh?", completion = "<Assistant Greely spots the Kaja'Cola Zero-One in your hand and her eyes seem to come to life.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25111] = { id = 25111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scavengers Scavenged", description = "Now that I know you're not squeamish, I've got another job for you. Have you seen the red-feathered birds swarming around the bones out there? Those are fire rocs. They'll light you up good if you're not careful.\n\nThey're also pretty darn valuable thanks to their unique anatomy. Most of the hunters loafing around here aren't up to the task of killing fire-spitting buzzards for money... think you can handle it?", sourceObjective = "Use Butcherbot to harvest 12 Fire Roc corpses.", completion = "Alchemists pay through the nose for these things. Sure, maybe I tell some of them they're dragon parts, but that ain't my problem, right?", sourceObjectiveStatus = "unverified-source-field" }
quests[25112] = { id = 25112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Butcherbot", description = "I make my money around here selling animal parts. I've been perfecting a foolproof method of maximizing profit: The butcherbot!\n\nThese little guys are programmed to harvest every scrap of usable material from the wildlife around here, on a case-by-case basis. He does all the work, and best of all, only I know how to get the goods back out of him.\n\nIf you're interested in making some coin, take one of these guys for a spin. I need some glasshide basilisk parts; you'll find a bunch of them to the south.", sourceObjective = "Use the Butcherbot to harvest 10 Glasshide Basilisk corpses.", completion = "Nice going, kid. Didn't lose any fingers? Good, we can get some more work for you then.", sourceObjectiveStatus = "unverified-source-field" }
quests[25115] = { id = 25115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blisterpaw Butchery", description = "The hyenas wandering the wastes here might look scrawny, but they've got some of the strongest jaws you'll find! If you're not careful, they'll take a leg off in one bite. That kind of bone strength is a valuable resource, my friend, just waiting to find a buyer!\n\nTake one of my Butcherbots with you. Jaw separation isn't an easy task, and this little guy has been set up to know exactly what to do. Just bring him back when he's full.", sourceObjective = "Use the Butcherbot to harvest 10 Blisterpaw Hyena corpses.", completion = "Beautiful! We'll have these puppies shined up and ready to sell in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[25118] = { id = 25118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking for Lurkers", description = "I don't know about you, but I'm not much a fan of spiders, much less the kind that come bigger than me. Loch Modan's a gorgeous place, but I'd say it could do without those horrid things waltzing around.\n\nTell you what, I've got some spare coin, and you look like a tough one. If you head out and off some of those things for me, I'll pay you for your time.", sourceObjective = "Kill 8 Forest Lurkers.", completion = "I'll rest easier knowing one of those lumbering things won't be wandering into my bedroom at night... again.  Thanks much.", sourceObjectiveStatus = "unverified-source-field" }
quests[25120] = { id = 25120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marley's Final Flight", description = "Okay, {name}! Let's take these artifacts to my father and give him our report firsthand.\n\nThanks to your help my flying machine is ready to roll. We can fly there together and share in the glory.\n\nTalk to me when you're all set to move out!", sourceObjective = "Talk to Marley Twinbraid and take a spin in his flying machine.", completion = "<The battered dwarf hangs limply from the cockpit. As you approach the burning wreckage, his eyes flutter open.>\n\n<Marley Twinbraid is still alive!>", sourceObjectiveStatus = "unverified-source-field" }
quests[25121] = { id = 25121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Momentum", description = "It looks like we've got more work to do! Having Mr. Noggenfogger ask us to take care of the rest of the pirates is a true honor.\n\nSince you've been SO helpful, why don't you meet me at Lost Rigger Cove? I've just got to slip into something a bit more comfortable, so don't wait on me. I'll beat you there, promise!", sourceObjective = "Meet Kelsey Steelspark at Lost Rigger Cove.", completion = "Hi there! The fun's already started!", sourceObjectiveStatus = "unverified-source-field" }
quests[25122] = { id = 25122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morale Boost", description = "You've got to get all the Kaja'Cola Zero-One that you can and make the goblins drink it to boost their morale and free them!", sourceObjective = "Use Kaja'Cola Zero-One to free Ace, Izzy, Gobber, and 6 Goblin Survivors or Kezan Citizens.", progress = "Increase their morale, {name}, so that they will run to freedom!", completion = "I hate the Trade Prince, but you can't argue with the results of his methods. Kaja'Cola Zero-One is a huge improvement over regular old Kaja'Cola at half the calories and twice the ideas!", sourceObjectiveStatus = "unverified-source-field" }
quests[25123] = { id = 25123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Throw It On the Ground!", description = "This nightmare will never be over while Blastshadow the Brutemaster still breathes. There are a couple of problems though.\n\nOne, being a warlock, he's got a succubus named Delicia Whipsnaps. If you kill Blastshadow quickly, the demon will go back to where it was summoned from.\n\nThe second problem, since Blastshadow is a warlock, he has a soulstone that allows him to resurrect. You have to get his soulstone and destroy it so that he'll be dead forever!", sourceObjective = "Destroy Blastshadow the Brutemaster's soulstone.", progress = "The soulstone is the key, {name}!", completion = "Your soulstone has expired, Blastshadow!", sourceObjectiveStatus = "unverified-source-field" }
quests[25125] = { id = 25125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light at the End of the Tunnel", description = "Okay, we have got to get out of here before she blows for good!\n\nLet's head out the other end of the tunnel on the north side of the mine. We should be able to use one of the mine carts for a quick ride down the side of the volcano.", sourceObjective = "Interact with the Mine Cart outside the Gallywix Labor Mine on the Lost Isles.", completion = "Looks a little rickety....", sourceObjectiveStatus = "unverified-source-field" }
quests[25126] = { id = 25126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting Teeth", description = "The first order of business will be to put a little strength in your backbone. I could send you out to the Barrens to hunt kodo, but well, in all honesty, you're more useful to us alive than dead.\n\nI believe you'll be of more use to us slaughtering the boars you'll find in the farms to the north and northeast of here.", sourceObjective = "Slaughter 6 Mottled Boars.", progress = "I hope you haven't returned to try and convince me that you have completed your task, {name}? No, of course not. I would think better of you.", completion = "Hmmm, not bad, {name}. But don't let it get to your head...you'll fight tougher than boars in your career.\n\nNonetheless, you've proven yourself well, and your next trial will be against a considerably more dangerous opponent, so you'll need some extra protection.", sourceObjectiveStatus = "unverified-source-field" }
quests[25127] = { id = 25127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sting of the Scorpid", description = "I must send you back into the fields again, {class}. You will find large numbers of scorpids northwest of here. Bring me eight of their tails.\n\nThe antidote for their sting is actually made from venom extracted from their stingers. We keep large quantities of antidote for scorpid venom on hand to heal young bloods just like you...\n\nBut I'm sure you won't be needing any of that, will you?", sourceObjective = "Obtain 8 Scorpid Worker Tails.", progress = "The carapace of a scorpid isn't so thick that the strength of a determined warrior will be deterred. Strike strongly and without doubt, and the scorpids should prove easy prey.", completion = "There is an important lesson that you must take away from fighting scorpids. The smallest or largest of opponents can still send you to your doom. In fierce combat, any number of things can prove your downfall.\n\nI have no more to teach you, {name}. You have done well, and I will watch your progress with interest.", sourceObjectiveStatus = "unverified-source-field" }
quests[25128] = { id = 25128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hana'zua", description = "Hey mon, take a knee and hear me out.  We got a problem.\n\nA good friend of mine, Hana'zua, has gone out into the valley and he hasn't returned.  Last I seen, he was headin' north, where the scorpids hunt.  Maybe you go take a look for him?  The spirits be tellin' me that he's not well.", sourceObjective = "Find Hana'zua in the Valley of Trials.", completion = "<Hana'zua groans in pain.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25129] = { id = 25129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sarkoth", description = "{class}! I thought I would die out here with none to know of it. While I was hunting the scorpids of the Valley, I came across a particularly vicious-looking one. Hurling myself at it, I managed to inflict a massive blow to its claw before it closed around my leg.\n\nI wasn't ready for its stinger though, and it sliced down and into my chest, cutting into my flesh and letting my blood. Please, you must kill the scorpid for me! My honor must be upheld! I fought it up on the plateau to the south.", sourceObjective = "Kill Sarkoth and bring his claw back to Hana'zua.", progress = "Ahhh... my father always said I would never amount to much, and here, lying beneath a tree as life seeps away, I'm afraid it looks like he was right.\n\nAt least I wish to die knowing that my last enemy in life lays dead.", completion = "My blow was not enough to kill him, but looking at the damage I inflicted gives me some small measure of pride. That small measure will be all I have to sustain myself if I die, and in that light, the short list of my life's accomplishments fills me with anger.", sourceObjectiveStatus = "unverified-source-field" }
quests[25130] = { id = 25130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Den", description = "Seeing the deed you have done for me steels my heart. I cannot fall so easily! I must endure!\n\nBut it remains that I cannot make the trek back to our settlement unassisted. Please, {name}, return and tell Gornek of my situation. Perhaps he can help me.", sourceObjective = "Bring the news of Hana'zua's plight to Gornek in the Valley of Trials.", completion = "From your description of the beast, I believe you must be speaking of Sarkoth! It is no wonder that Hana'zua was overtaken by it. Aid will be dispatched to him immediately, trouble yourself no more with Hana'zua's plight.\n\nHowever, I must say, I am most impressed to hear that you brought Sarkoth to death. It is a feat to be proud of, {name}. And that you would fight for a stranger's honor, while other tasks occupied your time, your own honor is heightened.", sourceObjectiveStatus = "unverified-source-field" }
quests[25131] = { id = 25131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vile Familiars", description = "I trust the Valley of Trials will teach you much, young {class}.\n\nI was sent to the Valley to guide you, but I have discovered a growing taint here...\n\nOne of the Burning Blade - a foul, demon-worshipping cult - has made camp here in the Valley of Trials.  He skulks in a cave to the north, and his vile familiars have spilled from its mouth to cause havoc.\n\nAs your first task against the Burning Blade, I bid you, defeat these familiars. Slay many and, if you survive, return to me.", sourceObjective = "Kill 8 Vile Familiars.", completion = "You have done well, {name}.\n\nAlthough the Vile Familiars were merely pets of the darker powers within the Burning Blade, your success against them foretells greater deeds ahead.", sourceObjectiveStatus = "unverified-source-field" }
quests[25132] = { id = 25132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Blade Medallion", description = "Through my divinations, I see that an item of power - a medallion - hides deep within the Burning Blade Coven, guarded by beasts and black magic.  We must have it.\n\nFor too long these demon-worshippers have defiled our homelands.  Cleanse the coven of its demonic taint by slaying the fel beasts and their leader.  Return with this medallion as proof of your deed.\n\nGo, {name}.  You will find the coven in a cave to the north.", sourceObjective = "Slay 7 Felstalkers and obtain the Burning Blade Medallion.", progress = "Is your task complete, {name}?", completion = "You retrieved it!  Well done!\n\nYour efforts within the Burning Blade Coven are key in rooting out this cult in the Valley of Trials.  But I fear they have further aims in our land.\n\nWe have not seen the end of them.", sourceObjectiveStatus = "unverified-source-field" }
quests[25133] = { id = 25133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Sen'jin Village", description = "Your trials against the Burning Blade are finished... here in the Valley.  But I want you to report your findings.\n\nGo to the troll village of Sen'jin and seek out Master Gadrin.  Sen'jin Village is east out of the valley, then right at the fork.\n\nTell Gadrin of the Burning Blade, and that they have reached the Valley of Trials.  Discover from him if they have yet reached Sen'jin.\n\nGo, {name}, and be swift.  I fear the evil found in the Burning Blade Coven is but the herald of a larger threat...", sourceObjective = "Speak with Master Gadrin in Sen'jin Village.", completion = "Hm... your report comes at a bad time.  The Burning Blade is no longer seen here in Sen'jin, but we will be vigilant in our efforts to prevent their return to the area.\n\nThe orcs are friends of the Darkspear Trolls.  Honorable friends.  We want to help the orcs, but... we need help too.", sourceObjectiveStatus = "unverified-source-field" }
quests[25134] = { id = 25134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lazy Peons", description = "Cursed peons!  They work hard gathering lumber from the trees of the valley, but they're always taking naps!  I need someone to help keep the peons in line.\n\nYou look like the right {race} for my task.  Here, you take this blackjack and use it on any lazy peons you find sleeping on the job.  A good smack will get them right back to work!  Return the blackjack when you're done.\n\nLook for them underneath the trees in the valley.  Lousy slacking peons...", sourceObjective = "Use the Foreman's Blackjack on 4 Lazy Peons when they're sleeping.", progress = "No good lazy...\n\n Eh?  Do you have my blackjack?  Did you catch any peons sleeping on the job?!", completion = "Good, good.  Maybe they'll think twice before slacking next time!  Thanks for the help!", sourceObjectiveStatus = "unverified-source-field" }
quests[25135] = { id = 25135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thazz'ril's Pick", description = "{name}, you are a dependable {race}.  Can I count on you for another task?\n\nSome time ago I was surveying the cave to the north for minerals, and I left my favorite pick behind.  When I later returned to retrieve it I found the cave was filled with vicious beasts!  Will you go into the cave, the Burning Blade Coven, and get my pick?\n\nI left it in a chamber with waterfalls.  My pick has a spell on it so you can see it in the dark, so you won't have to worry about finding it... just what's guarding it!", sourceObjective = "Bring Thazz'ril's Pick to Foreman Thazz'ril.", progress = "Have you entered the Burning Blade Coven, {name}?  Did you find my pick?", completion = "Great, you got it!  Thanks a lot, {name}.  This is my favorite pick!  Now if my peons ever finish chopping down these trees, maybe we can find a nice cave to mine!", sourceObjectiveStatus = "unverified-source-field" }
quests[25136] = { id = 25136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galgar's Cactus Apple Surprise", description = "It sure gets hot out here in the Valley of Trials.\n\n<Galgar wipes his brow.>\n\nIf only I had some cactus apples, I could make my famous cactus apple surprise! Nothing cools you off faster than a piece of that delicious treat.\n\nI'll tell you what, {name}. If you bring me 6 cactus apples, I'll make you a few portions of cactus apple surprise to take with you on your adventures. If you're interested, you can find cactus apples growing near the cactus plants around here.", sourceObjective = "Obtain 6 Cactus Apples.", progress = "Have you finished collecting cactus apples?", completion = "Wonderful, {name}! As promised, here is your cactus apple surprise plus a little something extra.", sourceObjectiveStatus = "unverified-source-field" }
quests[25138] = { id = 25138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphic Parchment", description = "Ah, while you were gone a parchment came for you, {name}.\n\nRead it when you have time. If I'm not mistaken, it came from the mage trainer Acrypha. She would have words with you when you're ready.", sourceObjective = "Read the Glyphic Parchment and speak with Acrypha in the Valley of Trials.", progress = "What?  Who are you?  Get away!\n\nOh, you're the other {class}, the new one, the one with the big arms.  Come on, let's get to work.", completion = "Ahh, where to start... introductions!  I'm Acrypha - the one who sent you that parchment - I've spent the last several years in an Undercity library, my head in a book.  I learned everything I could about the arcane, and now I've returned home to share it with grunts like yourself.\n\nShall we begin?", sourceObjectiveStatus = "unverified-source-field" }
quests[25139] = { id = 25139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steady Shot", description = "You already know how to fire an arcane shot.  Good.  But doing so depletes your focus.  To gain your focus back you will need to switch to a second type of ranged attack.  I can teach it to you.", sourceObjective = "Learn Steady Shot from Karranisha in the Valley of Trials. Locate a Training Dummy and practice using Steady Shot 5 times.", completion = "You learn quickly.", sourceObjectiveStatus = "unverified-source-field" }
quests[25141] = { id = 25141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eviscerate", description = "Let's start with the basics, shall we?  I'm the only rogue trainer in town, so you're going to have to learn it from me.\n\nHere's how it's going to go: you give me your money, and I'll teach you how to finish off a foe.  Do we have a deal?", sourceObjective = "Learn Eviscerate from Rwag in the Valley of Trials. Locate a Training Dummy and practice using Eviscerate 3 times.", completion = "You won't be sorry.  The ability to capitalize on the opportunities created by previous attacks is one of our greatest strengths.", sourceObjectiveStatus = "unverified-source-field" }
quests[25143] = { id = 25143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Strike", description = "I will teach you the art of the primal strike.  By following these steps, you can deal additional damage to your foes with your weapon.  Speak with me again and I will show you the way.\n\nAfter your lessons are complete, practice using the training dummies outside the Den.", sourceObjective = "Train Primal Strike from Shikrik in the Valley of Trials. Look for a training dummy near Shikrik and practice using Primal Strike 3 times.", progress = "We must continue your training before pressing forward, young {name}.", completion = "Very well.  Now that you know how to speak with the elements, we will test your bond with them.", sourceObjectiveStatus = "unverified-source-field" }
quests[25145] = { id = 25145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immolate", description = "It is my duty to train you, and I intend to do just that.  Speak with me again and I will show you how to wreathe your opponents in a demonic fire.\n\nOnce your lesson is complete, practice your new spell against one of the training dummies around here.", sourceObjective = "Train Immolate from Nartok in the Valley of Trials. Locate a Training Dummy and practice casting Immolate 5 times.", progress = "Once you have learned Immolate, then we can test your abilities.", completion = "You appear to be a quick learner.", sourceObjectiveStatus = "unverified-source-field" }
quests[25147] = { id = 25147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charge", description = "I've been instructed to prepare you for battle.  Though, from the look of you, it looks like you've already spent a little time out in the field.  Good.\n\nIt's been said that a warriors fight not only with their arms but their legs.  You must learn to move quickly around the battlefield .\n\nSpeak to me again, and I will teach you how to charge.", sourceObjective = "Train Charge from Frang in the Valley of Trials. Locate a Training Dummy and practice using Charge.", progress = "After we train, then we will test your abilities.", completion = "You understand now?  Good, let's try it out.", sourceObjectiveStatus = "unverified-source-field" }
quests[25149] = { id = 25149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Missiles", description = "Alright, here's the easy part.  All you have to do is listen to me.  And pay me a little bit of copper.\n\nSpeak with me again and we'll teach you the rite of Arcane Missiles. This isn't just an ordinary spell, {name}. Each time you attack with a spell, you'll have a chance to activate Arcane Missiles, so be attentive.\n\n Once your lesson is finished, practice your new spell against a training dummy.", sourceObjective = "Learn Arcane Missiles from Acrypha in the Valley of Trials. Locate a Training Dummy and practice using Arcane Missiles 2 times.", completion = "Good.  Now we practice.", sourceObjectiveStatus = "unverified-source-field" }
quests[25151] = { id = 25151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Needs Ale!", description = "<Marley grasps the side of your head with a shaking, bloody hand.>\n\nAle... Must... have ale...\n\nOl' Barkerstout from inside. <He coughs.> That should ... do the trick.", sourceObjective = "Search Bael'dun Keep for a Mug of Ol' Barkerstout and bring it to Marley Twinbraid at the entrance.", progress = "<Marley's breathing is ragged, coming and going in shuddering gasps.>\n\n<His eyes look at you imploringly.>", completion = "<Marley's eyes sparkle as you rush toward him with the ale. He grasps the mug in both of his shaking hands and upends it, white foam spilling out over his blood-caked beard.>\n\nAh... that's the stuff. Ol' Barkerstout... Thank you, friend.\n\nThat'll make this... a little easier.\n\n<Coughing one final time, he slumps over the shattered control console, the half-empty mug crashing to the ground and spilling its contents into the sand. His eyes glaze over.>\n\n<Marley Twinbraid is dead.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25152] = { id = 25152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Place In The World", description = "Finally, you are of age, {name}... of age to battle in the name of the Horde. To conquer for the glory of the Warchief.\n\nYes...\n\n<Kaltunk looks you over.>\n\nYou will do nicely.\n\nNo doubt you wish to find a great dragon or demon and strangle it with your bare hands, but perhaps it would be wise to start on something less... dangerous.\n\n<Kaltunk laughs.>\n\nReport to Gornek, he should be able to assign a task better suited to a young {class}. You will find him seated at the fire behind me.", sourceObjective = "Speak with Gornek.", completion = "Another one of Kaltunk's recruits, hm?\n\nA sorry state of affairs we find ourselves in if this is the best the Horde can produce. No matter. By the time we think you're ready to leave the Valley, you'll be a proud warrior of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[25153] = { id = 25153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bael'dun Rescue", description = "Help - Help! You've got to do something!\n\nSome dwarves are still inside - so many - they're trapped in the debris. Buried alive. The flames! It's a nightmare in there. We don't know how much longer until the roof collapses...\n\nPlease, {class}, you've got to save them!\n\nRun inside. Use the emergency fire valves to protect yourself from the flames. You're the only hope they have...", sourceObjective = "Go into Bael'dun Keep and rescue 10 Bael'dun Survivors from the rubble.\n\nUse the Emergency Fire Valves to protect yourself from the flames.", completion = "You're a legend, {name}.\n\nThe other survivors and I will be telling the story of your deeds for years to come.", sourceObjectiveStatus = "unverified-source-field" }
quests[25154] = { id = 25154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Present for Lila", description = "I'm trying to impress this trade ship captain Lila.  I've been working on a necklace to match her lovely purple hair, but the gems have gone missing!  They were there when I was showing them off to my good friend Curver last evening.  We were drinking moonshine and I blacked out - when I woke up the gems were gone!  They must have been darn good thieves, because Curver didn't see anything.\n\nHer ship is coming in tonight, and I really need three nightstones to get her present done.  Help me out here!", sourceObjective = "Cut three Timeless Nightstones and give them to Isabel Jones in Stormwind City.", progress = "Have you brought me the nightstones?", completion = "Thanks!  I'm sure to beat out that Marith Lazuria in Orgrimmar with these!  I can't wait to see the look in her beautiful eye when I give this to her.", sourceObjectiveStatus = "unverified-source-field" }
quests[25155] = { id = 25155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogrezonians in the Mood", description = "I was supposed to receive a shipment of jasper from Azeroth Express, but I just heard their ship crashed into some tiny island called Ogrezonia.  I worry about the crew, as the giant female ogres on the island are rumored to perform horrible rituals on men who happen upon their island.  My work must go on, though, and we need those gems.  I've heard great things about your skill as a jewelcrafter - could you deliver three jagged jaspers by the end of the day?", sourceObjective = "Cut three Jagged Jaspers and give them to Isabel Jones in Stormwind City.", progress = "Have you brought me the gems I need?", completion = "Your work is as good as it is rumored to be!", sourceObjectiveStatus = "unverified-source-field" }
quests[25156] = { id = 25156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Goo", description = "Instead of using the tired old method of setting gems into rings and such, I use an innovative new method.  I simply glue on the gems with Barnsworth Elemental Glue!  The professor needs more elemental goo for another batch, though, and I have a whole bunch of setting to do.  Can you go get me some?", sourceObjective = "Collect 10 Elemental Goo from any Cataclysm elemental and bring them to Isabel Jones in Stormwind City.", progress = "Did you bring me the elemental goo?", completion = "Thanks.  Erm.  Just set them over there.  I need to figure out how to get my hand off of this jar�", sourceObjectiveStatus = "unverified-source-field" }
quests[25157] = { id = 25157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Latest Fashion!", description = "Professor Barnsworth has been working on this new stardust - what with the fashion in Stormwind this season being about all things sparkly, I'm sure if we can get it to the market it will be all the rage!  The Jewelcrafter's Association, however, won't let us market it until we've completed some humanoid testing - something about tinkering with magical dust being dangerous or some such nonsense.  Well, I suppose we need to humor them.  Take this bag and test out Stardust No. 2 on some humanoid subjects.", sourceObjective = "Test Stardust No. 2 on 10 \"humanoid subjects\".", progress = "How did the tests go?", completion = "It did what!?  We're ruined!  Hmm.  Well, actually... Maybe the professor can find some other applications for it?", sourceObjectiveStatus = "unverified-source-field" }
quests[25158] = { id = 25158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nibbler! No!", description = "Lila's pet Nibbler got into my workshop again!\n\nI was making a bracelet, to be delivered today.  The work was almost done, except for the gems.  I spent all night cutting them, but when I stepped out for a bit of breakfast, the little beast came into my workshop and swallowed every gem in sight!  The thing can digest ANYTHING, and trust me, you'd break your back trying to pick up its leavings.\n\nI need to get replacement gems fast; the courier is coming in tonight.  Help!", sourceObjective = "Cut three Solid Zephyrites and give them to Marith Lazuria in Orgrimmar.", progress = "Have you brought me those solid zephyrites I need?", completion = "You've really saved my skin, {name}.  Thanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[25159] = { id = 25159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Latest Fashion!", description = "Dr. Vernstrom has been working on this new stardust - what with the fashion in Orgrimmar this season being about all things sparkly, I'm sure if we can get it to the market it will be all the rage!  The Jewelcrafter's Association, however, won't let us market it until we've completed some \"live testing\" - something about tinkering with magical dust being dangerous or some such nonsense.  Well, I suppose we need to humor them.  Take this bag and test out Stardust No. 2 on humanoid subjects.", sourceObjective = "Test Stardust No. 2 on 10 \"humanoid subjects\".", progress = "How did the tests go?", completion = "It did what!?  We're ruined!  Hmm.  Well, actually...  Maybe the doctor can find some other applications for it?", sourceObjectiveStatus = "unverified-source-field" }
quests[25160] = { id = 25160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Present for Lila", description = "I'm trying to impress this trade ship captain Lila.  I've been working on a necklace to match her lovely purple hair, but the gems have gone missing!  They were there when I was showing them off to my good friend Bonder last evening.  We were drinking moonshine and I blacked out - when I woke up the gems were gone!  They must have been darn good thieves, because Bonder didn't see anything.\n\nHer ship is coming in tonight, and I really need three nightstones to get her present done.  Help me out here!", sourceObjective = "Cut three Timeless Nightstones and give them to Marith Lazuria in Orgrimmar.", progress = "Have you brought me the nightstones?", completion = "Thanks!  I'm sure to beat out that Isabela Jones in Stormwind with these!  I can't wait to see the look in her beautiful eye when I give this to her.", sourceObjectiveStatus = "unverified-source-field" }
